quests[6386] = { id = 6386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Razor Hill", description = "My wind riders are trained to fly to many different places, as long as you have already been to that place and spoken with the wind rider master there.\n\nYou have been to Razor Hill and spoken to their wind rider master Burok, so now you can fly directly to him from here.  Once you're at Razor Hill, you can deliver Gryshka's letter to Grimtak.\n\nSpeak with me when you are ready to go.", sourceObjective = "Buy a wind rider to Razor Hill from the wind rider master Doras, then bring Gryshka's Letter to Grimtak at Razor Hill.", progress = "Have you returned from Orgrimmar?  Did Gryshka like the meat I sent her?", completion = "Hah!  I guess she liked it!  Nothing brings red to a lady's cheeks like a big, juicy steak!\n\nThank you, {name}.  You've done me a great service.  Here is some money for your trouble, and don't be surprised if I invite you to my wedding!", sourceObjectiveStatus = "unverified-source-field" }
quests[6387] = { id = 6387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor Students", description = "I see a lot of young dwarves at my door, eager to learn the trade of cooking.  And if there's one thing a cook needs more than anything, it's a cleaver!\n\nI have a list of students who scored high in their lessons and earned an honorary cleaver.  Take my list to Golnir Bouldertoe in Ironforge.  He'll get the cleavers ready.\n\nThe fastest way to Ironforge is on a gryphon, so bring the list to our gryphon master, Brolan Galebeard, and speak with him about transport to Ironforge.", sourceObjective = "Bring Gremlock's List to Brolan Galebeard in Kharanos.", progress = "Have you had your fill of Thelsamar so soon?  Are you ready to leave for another city?", completion = "You have to get this to Ironforge, eh?  For a small fee I can put you on the back of one of my gryphons, and it'll take you there.  How does that sound?", sourceObjectiveStatus = "unverified-source-field" }
quests[6388] = { id = 6388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gryth Thurden", description = "Here are the honorary cleavers for Gremlock's students.  If you've already been to Kharanos, then you should fly a gryphon back there!\n\nTake the cleavers to our gryphon master, Gryth Thurden, and speak with him about a ride back to Kharanos.", sourceObjective = "Bring the Honorary Cleavers to Gryth Thurden in Ironforge.", progress = "You look like you have somewhere to go.  Need one of my gryphons?", completion = "You have to get these to Thelsamar, eh?  That won't be a problem.  As long as you've already been to Thelsamar and spoken to Thorgrum Borrelson, then you can take one of my gryphons back to him.", sourceObjectiveStatus = "unverified-source-field" }
quests[6389] = { id = 6389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plague Upon Thee", description = "You look around the lumber mill for something suitable to open the barrel with. You find a crowbar that looks like it will do the trick.\n\nYou set your feet and pray that you'll be able to get out of the mill before the termites get to you.", sourceObjective = "Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.", progress = "Have you done it, {name}? Have you released the termites? The Light help us if the Scarlet Crusade were able to hold onto both the mill and Hearthglen. They should have neither. They're just capitalizing on the victims of the last war and should be put down like rabid animals!", completion = "Haha! Thank you, {name}! You've done it! My father's spirit can now rest and I can live in peace.\n\nThank you again. If there is anything I can do for you, please, just ask.", sourceObjectiveStatus = "unverified-source-field" }
quests[6390] = { id = 6390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plague Upon Thee", description = "You look around the lumber mill for something suitable to open the barrel with. You find a crowbar that looks like it will do the trick.\n\nYou set your feet and pray that you'll be able to get out of the mill before the termites get to you.", sourceObjective = "Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Mickey Levine at the Bulwark in Tirisfal Glades.", progress = "Have you done it, {name}? Have you released the termites in the lumber mill?\n\nIt was bad enough that my family lost their jobs and lives, but then to see the place where my childhood was spent taken over by those disgusting so-called holy men... pfah!!", completion = "Thank you, {name}. Here, take this coin. I'm sorry it's not more, but try to take some joy in helping destroy the Scarlet Crusade's efforts!", sourceObjectiveStatus = "unverified-source-field" }
quests[6391] = { id = 6391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ride to Ironforge", description = "For just a few coins, one of my gryphons will take you to Ironforge.  From there, deliver Gremlock's list to Golnir Bouldertoe.  You'll find him in the Deep Mountain Mining Guild.  That's in the Great Forge District of Ironforge, which is right where my gryphon will drop you off!\n\nSpeak to me again when you're ready for the journey.", sourceObjective = "Buy a gryphon to Ironforge from the gryphon master Brolan Galebeard, then bring Gremlock's List to Golnir Bouldertoe in Ironforge.", progress = "What can I do for you, sir?", completion = "Ah, the lastest list of Brock's best pupils.  I have a batch of honorary picks ready to go.  I just need to chisel in the names of the students...", sourceObjectiveStatus = "unverified-source-field" }
quests[6392] = { id = 6392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Gremlock", description = "For a small fee you can buy a gryphon ride to Kharanos... as long as you've already been there.  Gryphons will only fly you to places you've already been, so be sure to speak with every gryphon master you see so you can fly to him later.\n\nYou've already been to Brolan, the gryphon master of Kharanos, so now you can return to him.  And once in Kharanos, you can deliver the cleavers to Gremlock Pilsnor.\n\nSpeak with me when you're ready to go.", sourceObjective = "Buy a gryphon to Kharanos from the gryphon master Gryth Thurden, then bring the Honorary Cleavers to Gremlock Pilsnor in Kharanos.", progress = "Ah, {name}.  Have you returned from Ironforge?", completion = "You brought the picks.  Great!  I'll get these to my mining students.  I'm sure they're eager to use them on the ore deposits of Loch Modan.\n\nThank you for your help, {name}.  I am in your debt, but I hope this money will at least cover your travel costs.", sourceObjectiveStatus = "unverified-source-field" }
quests[6393] = { id = 6393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental War", description = "The Tribunal of the Tides has sent me to wage war on the fire elementals here in Stonetalon Mountain. Neptulon the Tidehunter, Lord of all water elementals, has taken a personal interest in seeing our fiery cousins extinguished.\n\n{name}, you can help me gain favor with the Tribunal by destroying the fire elementals in Charred Vale. When destroyed, the fire elementals leave Incendrites. Return these to me and be rewarded.", sourceObjective = "Bring 10 Incendrites to Tsunaman at Sun Rock Retreat.", progress = "The Tribunal of the Tides grows impatient. They seek to end this war that has raged across all dimensions for eons. My brethren are anxious to hear news of the glorious victory over the hated fire elementals. Have you the Incendrites that I require?", completion = "The water spirits within me bubble with the excitement. {name}, you have given me a glorious victory to report to the Tribunal of the Tides.", sourceObjectiveStatus = "unverified-source-field" }
quests[6394] = { id = 6394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thazz'ril's Pick", description = "{name}, you are a dependable {race}.  Can I count on you for another task?\n\nSome time ago I was surveying the cave to the north for minerals, and I left my favorite pick behind.  When I later returned to retrieve it I found the cave was filled with vicious beasts!  Will you go into the cave, the Burning Blade Coven, and get my pick?\n\nI left it in a chamber with waterfalls.  My pick has a spell on it so you can see it in the dark, so you won't have to worry about finding it... just what's guarding it!", sourceObjective = "Bring Thazz'ril's Pick to Foreman Thazz'ril.", progress = "Have you entered the Burning Blade Coven, {name}?  Did you find my pick?", completion = "Great, you got it!  Thanks a lot, {name}.  This is my favorite pick!  Now if my peons ever finish chopping down these trees, maybe we can find a nice cave to mine!", sourceObjectiveStatus = "unverified-source-field" }
quests[6395] = { id = 6395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marla's Last Wish", description = "My friend Marla Fipps lived with her husband Samuel before the plague, but when the plague came Samuel succumbed and joined the Scourge's ranks.\n\nMarla was spared an undeath only to die at the hands of her now mindless husband.  So strong was her love, however, that her last dying wish was to be buried with her beloved Samuel.\n\nSamuel Fipps roams at a ruined camp along the road northeast of Deathknell.  Defeat him and grant Marla's wish: bury him at her grave, in the first row of our graveyard.", sourceObjective = "Bring Samuel Fipps' Remains to Marla's Grave, then return to Novice Elreth.", progress = "We must respect our dead, {name}.  It is one of the ways in which we differ from the Scourge...", completion = "You have done a good deed today, {name}.  Although our struggle against the Scourge continues, let us hope that Marla and Samuel will find peace together in their final resting place.", sourceObjectiveStatus = "unverified-source-field" }
quests[6401] = { id = 6401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaya's Alive", description = "Tell Tammra Windfield, Kaya's aunt who's at Sun Rock Retreat, about the good news! Kaya is alive! We had thought she was lost after the brutal attack on our village. Follow the path to the west to get to Sun Rock Retreat.", sourceObjective = "Tell Tammra Windfield in Sun Rock Retreat the good news.", completion = "My goodness, my niece Kaya is alive! That is good news indeed. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6402] = { id = 6402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormwind Rendezvous", description = "You are to meet with Windsor at the gates of Stormwind.\n\nWhat Windsor is about to unveil will shake the very foundation of the kingdom!\n\nDo not attempt to venture there alone, {name}. You must amass an army! Gather your compatriots. To arms!", sourceObjective = "Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived.", completion = "Before we begin, I ask that you first gather an army. We face a dragon, after all!", sourceObjectiveStatus = "unverified-source-field" }
quests[6403] = { id = 6403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Masquerade", description = "It has been quite the adventure, friend. I owe you a great debt of gratitude. Perhaps, when all is said and done...\n\nAs you have no doubt ascertained by now, Lady Prestor is Onyxia: Brood of Deathwing, twin to the tyrant of the Spire, Nefarian.\n\nFor too long she has held our kingdom in her captivating gaze. Even the Highlord is controlled by her trickery - a puppet. It all ends today... The spell will be broken.\n\nWorry not, for together, we shall be victorious!\n\nAre you ready?", sourceObjective = "Follow Reginald Windsor through Stormwind. Protect him from harm!", progress = "I... I... I was powerless.", completion = "<Bolvar holds the shattered medallion.>\n\nThe magic held within must be reignited. The dragon's eye must be attuned.\n\nWindsor's sacrifice has freed our Kingdom, but the threat of Onyxia and her kin is ever looming.\n\nThis medallion is what held my mind and body captive. It is also what gave me access to Onyxia's own mind - to her secrets. Albeit the visions are muddled now, some things I do remember.", sourceObjectiveStatus = "unverified-source-field" }
quests[6421] = { id = 6421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boulderslide Ravine", description = "Something is amiss here in Stonetalon. Can you feel the tension in the air, {name}?\n\nSoutheast of here lies a deep cave in Boulderslide Ravine. The kobolds there are frantically mining a rare crystal called Resonite. I need you to bring back some ore samples so that I can understand what's happening in that cave.  I also need you to investigate the depth of that cave.\n\nGo young {class}, it's imperative I know what evil lurks under these mountains.", sourceObjective = "Explore deep into the cave at Boulderslide Ravine and bring back 10 Resonite Crystals for Mor'rogal at Sun Rock Retreat to investigate.", progress = "What news have you discovered from Boulderslide Ravine? I recall some legend that deals with Resonite... I just cannot place my hoof on it. Perhaps knowing what lies at the bottom of the cave will illuminate their devious intentions.", completion = "Ah... Yes! That's it; the Resonite crystals have a trace of Earthen magic. The kobolds must have dug deep uncovering an Earthen.\n\nLegend states that the Earthen are creatures created by the Titans.  They were used to create the land our feet walk on. This most definitely is a threat that cannot be ignored.\n\n<Mor'rogal shakes his head.>\n\nPerhaps I can enchant these ore samples to use against this kobold plot.", sourceObjectiveStatus = "unverified-source-field" }
quests[6441] = { id = 6441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyr Horns", description = "Heya! I've been traveling through Ashenvale, heading towards Ratchet, and decided to make a stop here at Splintertree. I'm always looking for an opportunity, and it seems that satyr horns are in high demand in Ratchet these days.\n\nAfter asking around here, it seems that the satyrs in Night Run, Satyrnaar, and Xavian all have the type of horns I am looking for. I'm no match for those satyrs... but you look like you might be!\n\nTell you what, you collect the horns for me and I'll make it worth your time.", sourceObjective = "Collect 16 Satyr Horns for Pixel in Splintertree Post.", progress = "I hope you can be quick about getting those horns, {name}. I'm heading back to Ratchet soon!", completion = "These are perfect, {name}! Thanks for helping me out!\n\nOh, and this is for your time...", sourceObjectiveStatus = "unverified-source-field" }
quests[6442] = { id = 6442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga at the Zoram Strand", description = "There is evil lurking here along the coast, {race}.\n\nIt is the resting place of the doomed city of Zoram, long destroyed and submerged beneath the seas.  Lost, and nearly forgotten.\n\nNow, the naga have returned, and for what reason we do not know.  But reason matters little; we must defend the land we have worked so hard to claim as our own.\n\nReturn to me with 20 of their heads! Throw the naga back to the depths!", sourceObjective = "Bring 20 Wrathtail Heads to Marukai along the Zoram Strand.", progress = "The naga increase in numbers, {name}. Please complete this task for me.", completion = "We could use more of your kind around here, {name}. Thank you for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[6461] = { id = 6461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Feeders", description = "We Trolls here at Malaka'Jin have prospered from the land; Stonetalon Mountain offers great hunting for us to live on.\n\nLately, we have attracted the wrong dinner guests... the spiders in these mountains have been raiding our camps at night looking to steal our hunt.\n\nIf you were to help us kill off these ghastly beasts we at Malaka'Jin would be in your debt. Spiders are everywhere in Stonetalon - just head north from here and you will see what I am talking about.", sourceObjective = "Xen'zilla at Malaka'Jin needs you to kill 10 Deepmoss Creepers and 7 Deepmoss Venomspitters.", progress = "Hey mon, have you slain the hairy blood feeders? I fear none here in Stonetalon but I don't go walking around here at night... if you know what I mean mon!\n\nAs long as I stay off their dinner plate then all is well.\n\nGood luck to you, {class}!", completion = "Sweet, mon! Good news, perhaps we will have fewer unwanted dinner guests tonight.\n\nMany thanks, {name}.  We are forever in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6462] = { id = 6462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Charm", description = "My kinfolk were traveling here with many sacred troll charms, but the Thistlefur furbolgs attacked and killed them before they reached Zoram'gar!  Those vile furbolgs!\n\nI miss my brothers and sisters who were killed, but we will meet again in the afterlife.  However, their troll charms hold great value in this world.  It is an outrage that the furbolgs have them!\n\n{name}, you must retrieve the charms!  They are in chests in Thistlefur Hold, a cave at the end of Thistlefur Village, north of Astranaar.", sourceObjective = "Bring 8 Troll Charms to Mitsuwa at Hellscream's Watch.", progress = "Did you find the charms, {name}?  Every moment the furbolgs possess those sacred items, my blood boils with rage!", completion = "You found them!  Thank you!  Thank you, {name}!  You do not know how great a thing you have done for me.\n\nA troll without his charm is like an orc without his battle scars...\n\nWorthless.", sourceObjectiveStatus = "unverified-source-field" }
quests[6481] = { id = 6481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earthen Arise", description = "You have uncovered a dark threat to the land, {class}. The Resonite cask you have found in that cave houses a slumbering Earthen by the name of Goggeroc.\n\nI have changed the mixture of the Resonite crystals that you gathered with my shamanistic powers. Take the enchanted Resonite crystal and smash open the Resonite cask, which houses the Earthen.\n\nWhen awakened, Goggeroc will be weakened... Slay him, {name}!", sourceObjective = "Open the Resonite cask with the Enchanted Resonite Crystal, and then slay Goggeroc. Return to Mor'rogal with the news and Enchanted Resonite Crystal.", progress = "I fear if we do not dispose of this threat immediately, all of Stonetalon will be lost. The might of an Earthen can not be matched by any means. When awakened, Goggeroc will be weak from his long slumber, this will be the opportunity that you must take advantage of... go now {name}!", completion = "You bear good news, {class}! I fear the possibilities of what an Earthen would mean to Kalimdor.\n\nSlaying Goggeroc was a task for no one less than a hero. You have done well; all of Stonetalon and Kalimdor are indebted to you, noble {class}.\n\nAccept this as your reward most honored one.", sourceObjectiveStatus = "unverified-source-field" }
quests[6482] = { id = 6482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freedom to Ruul", description = "Eh?  Who are you?\n\n{name}?  You're no furbolg.  They are cursed!  They thought I was a bear and captured me, and now they starve me!  My strength is failing...\n\nHelp me escape, then speak with my sister Yama at the Splintertree Post to the east.\n\n{name}! I must escape!", sourceObjective = "Escort Ruul, then speak with Yama Snowhoof in Splintertree Post.", completion = "You found my brother!  He was captured by the Thistlefurs?  That is terrible news to hear, for although many Furbolgs are noble creatures, the Thistlefurs are corrupt.\n\nThank you for rescuing my brother, {name}.  I do not want to think of how they treated poor Ruul.  He will likely sleep long after this ordeal...", sourceObjectiveStatus = "unverified-source-field" }
quests[6501] = { id = 6501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dragon's Eye", description = "A fragment of the shattered medallion is all that I can offer.\n\nYou must find another of dragon blood willing to assist you in forging a new key. Once you secure this key, you must travel to the Wyrmbog in Dustwallow Marsh. It is there that you will find her lair, {name}.\n\nWhere to find other flights willing to help? Sadly, I do not know... They are said to exist. Some may even work and live among us, disguised as one of the humanoid races. I wish you luck.", sourceObjective = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist.", progress = "I sense an aura of evil radiating from you, {race}. What could you hold that emits such an aura?", completion = "I should have known - a piece of the black dragon brood mother, Onyxia. How revolting...", sourceObjectiveStatus = "unverified-source-field" }
quests[6502] = { id = 6502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drakefire Amulet", description = "It is a piece of the dragon; a scale - enchanted and transformed. Whole, it could have granted access to the beast's lair. Shattered, it is useless.\n\nIt is possible to repair the item, but to do so would require the blood of a black dragon champion. There is one... He is known as General Drakkisath, ruler of the dragonspawn armies of Nefarian. Perhaps you have heard of him?\n\nReturn with his blood, {race}, and I shall enchant the fragment into something that will grant you access to Onyxia's lair.", sourceObjective = "You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire.", progress = "The flow of time does not stop or slow, {race}. While my life is eternal, yours is not. Waste not the time that you have...", completion = "This amulet will grant you the access that you seek. The lair of Onyxia can be found in Dustwallow Marsh. As long as you hold the amulet, her wards cannot prevent you from entering.\n\nThe Blue Flight wishes you luck, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6503] = { id = 6503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale Outrunners", description = "Blasted elves! Dey knew right where to hit us!\n\nIt was dem outrunners... I tried to warn 'em that we were being spied on, but no one listened. Now look at us - cooped up here like chickens!\n\nNever too late for vengeance, mon! Hunt 'em down and make 'em pay for what they done!", sourceObjective = "Kill 9 Ashenvale Outrunners.", progress = "I await reports of your outrunner kills, {name}.", completion = "Very good, {name}.  Your hunting skills are impressive...\n\nThe loss of those outrunners helps blind the Alliance, and when they lack intelligence they are less likely to launch attacks.", sourceObjectiveStatus = "unverified-source-field" }
quests[6504] = { id = 6504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Pages", description = "I just picked up this shredder from Ratchet and I was on my way back to the Warsong Lumber Camp, where I am supposed to be on duty. I was given a manual on how to operate the shredder, but on the trip back, a huge gust of wind blew it from my hands. The pages went everywhere, and all I was left with was the cover.\n\nThe pages could be just about anywhere by now, I suppose... but I don't know how to use the shredder without them! Will you find them for me?", sourceObjective = "Find the 12 missing pages of the Shredder Operating Manual, and put them together to form Chapters 1, 2, and 3. Return the pages to Gurda Ragescar near Splintertree Post.", progress = "I hope you find the pages soon, {name}! I really need to get back to work!", completion = "Reading isn't my strong point... but now I'll be able to get back to work! Thanks, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[6521] = { id = 6521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unholy Alliance", description = "Malcin claims he is outside Razorfen Downs. This ambassador must be slain--his mission a failure in the eyes of the Lich King.\n\nHis presence there does explain much of what we've discovered about the area--some of the quilboar have grown frightfully powerful while showing signs of the Plague in their own way. Truly that must be a sign of some sort of deal they've struck.\n\nFind Malcin and slay him, {name}. Return to me after the deed is done.", sourceObjective = "Bring Ambassador Malcin's Head to Bragor Bloodfist in the Undercity.", progress = "Have you found the Ambassador, {name}? Is he dead?\n\nWe cannot afford to allow the Scourge to take a foothold on Kalimdor. They are enough of a threat to our own borders to have to deal with them on two fronts.\n\nThe only optimistic sign from the events you've told me about is that the crone seemed uncorrupted. She must know deep in her spirit that the Scourge may bring great power, but that the Barrens would not truly be hers if she were to agree to their deal.", completion = "Good. Well done, {class}.\n\nNow that Malcin is dead, we can at least know that the Scourges advances will be halted. The Dark Lady thanks you for your efforts and wishes to reward you with a gift.\n\nAlthough we do not know the extent of the Scourges influence within the Downs, I am sure we will discover their plots soon enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[6522] = { id = 6522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unholy Alliance", description = "My Lady,\n\nYou know very well what it is we are offering. The opportunity for you to take the Barrens and the lands beyond is a great one. We simply want your aid in return. By aid we mean nothing more than your giving us the freedom to take action in the area.\n\nPlease, allow us to discuss this further. We have great power and are willing to share with those wise enough to join us. I will remain outside Razorfen Downs for the time being.\n\nBest Regards,\nAmbassador Malcin", sourceObjective = "Take the Small Scroll to Bragor Bloodfist at the Royal Quarter in the Undercity.", progress = "What business is it you wish to speak of, {name}? You must feel it is important if you continue to pester me.", completion = "I recognize the insignia on this scroll, {name}. You found this on that crone who reigns over Razorfen Kraul? Interesting.\n\nThe Scourge aren't content with one continent it seems. This Ambassador Malcin--the one who wrote the note--is one of the Scourge's plagued servants, a human diplomat to the kingdom of Lordaeron before things... changed.\n\nIf the Scourge are trying to gain a foothold in Kalimdor, then it is up to us to act.", sourceObjectiveStatus = "unverified-source-field" }
quests[6523] = { id = 6523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protect Kaya", description = "Thank you for rescuing me! We must leave quickly before they discover that I am free. Please escort me to Camp Aparaje. From there, I know my way.\n\nMy father, Makaba Flathoof, will be desperate to know that I am safe.", sourceObjective = "Escort Kaya Flathoof to Camp Aparaje, and then return to Makaba Flathoof near the southeastern edge of Stonetalon.", completion = "Kaya is alive! {name}, I have you to thank for rescuing her.", sourceObjectiveStatus = "unverified-source-field" }
quests[6541] = { id = 6541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Kadrak", description = "Have you ever been to Ashenvale, to the north? The horde has recently set up an outpost on the Zoram Strand there, and we can always use some new recruits to help defend our new fronts.\n\nIf you think you are up to it, see Kadrak in the northern Barrens, at the watch tower. He is heading up the Ashenvale campaign and can give you further orders.", sourceObjective = "Report to Kadrak at the watch tower in Northern Barrens.", completion = "Ashenvale is a divided land, but our most recent efforts have been very successful. We not only have an outpost at the Zoram Strand, but another just north of here called Splintertree.", sourceObjectiveStatus = "unverified-source-field" }
quests[6542] = { id = 6542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Kadrak", description = "Have you ever been to Ashenvale, to the north? The horde has recently set up an outpost on the Zoram Strand there, and we can always use some new recruits to help defend our new fronts.\n\nIf you think you are up to it, see Kadrak in the northern Barrens, at the watch tower. He is heading up the Ashenvale campaign and can give you further orders.", sourceObjective = "Report to Kadrak at the watch tower in northern Barrens.", completion = "Ashenvale is a divided land, but our most recent efforts have been very successful. We not only have an outpost at the Zoram Strand, but another just north of here called Splintertree.", sourceObjectiveStatus = "unverified-source-field" }
quests[6543] = { id = 6543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warsong Reports", description = "I recently deployed a few scouts into Ashenvale and I need a runner to take them their orders, and bring me back a report of what they have observed.\n\nYour first stop should be the Zoram'gar Outpost, along the coast to the west, at the Zoram Strand, to locate the first runner. You also need to stop at Splintertree Post, to the north, and along the road to the east, near Azshara. You will find a scout and an outrider there.\n\nGive them each a report, and from them, get an update on their findings.", sourceObjective = "Open the Bundle of Reports. Take the Warsong Reports to the Warsong Scout, Warsong Runner, and Warsong Outrider. Bring back the updates they give you to Kadrak at the northern watch tower in the barrens.", progress = "Hurry, {name}. They must receive their reports; it is urgent.", completion = "I can see that you are one that can be counted on. These updates are crucial to our plans to further our presence in Ashenvale. We can now plan our next move.", sourceObjectiveStatus = "unverified-source-field" }
quests[6544] = { id = 6544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torek's Assault", description = "Hey!  {class}!  Come here!\n\nMy raiders and I are about to attack the Silverwing Outpost to the west.  Our target is its leader, Duriel Moonfire.  Scouts report the outpost is defended heavily with sentinels and warriors.  The battle will be glorious!\n\nDo you want to share in the glory, {name}, and aid us?  If so, then when it's over you can report our success to my superior, Ertog Ragetusk in Splintertree.\n\nWhat do you say.  Are you with us?", sourceObjective = "Escort Torek on his attack against Silverwing Outpost and Duriel Moonfire, then report to Ertog Ragetusk at Splintertree Post.", completion = "So Torek's attack was successful!  Well done, {name}.  Night elves are decent foes.  A little skinny, but strong and fierce!  I'm sure the battle was something to see...\n\nAnd I hope you gained a scar or two!", sourceObjectiveStatus = "unverified-source-field" }
quests[6545] = { id = 6545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warsong Runner Update", progress = "So you're here with my orders? Always good to see a new recruit with an exuberant nature and a strong will.\n\nYou'd best learn fast if you expect to keep up here. The threat of the naga grows, {name}. I have observed and have taken up defenses against several attacks on this outpost since I arrived here.\n\nBut if you'd like to pitch in with that effort, speak with one of the others here at the outpost.", completion = "Well, my update will explain all of this to Kadrak. You must return this to him as quickly as possible." }
quests[6546] = { id = 6546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warsong Outrider Update", progress = "Much danger lies along this path, {name}. You'd do best to remember this while traveling in these lands. The threat of the alliance is quite near.\n\nWe are faced by enemies on all fronts. The satyr are a formidable and prevalent force in eastern Ashenvale.  I have also discovered that the naga have taken over a large area of the land of Azshara.\n\nIt's good to see that we are still bolstering our numbers -- be ready for what lies ahead, {name}.", completion = "Take my update to Kadrak. Swiftly, {name}." }
quests[6547] = { id = 6547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warsong Scout Update", progress = "Keep an eye out, {race}. The elves are often hiding in the shadows...\n\nWe must always be watching. We have worked very hard to claim this land, and the elves are looking for a chance to take it from us.\n\nI assume you have my next orders from Kadrak?", completion = "Let Kadrak know of the success we have had here holding off the night elves. Our plans are going well." }
quests[6548] = { id = 6548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenge My Village", description = "The Grimtotem Clan raided my village and killed most everyone. I killed all I could, but barely escaped with my life.\n\n{name}, all I wish now is that more of them are dead. You will find them just to the west of here.", sourceObjective = "Kill 8 Grimtotem Ruffians and 6 Grimtotem Mercenaries, and then return to Makaba Flathoof near the southeastern edge of Stonetalon.", progress = "Have you killed them yet?", completion = "{name}, I thank you... but I will never forget what the Grimtotem have done to my village.", sourceObjectiveStatus = "unverified-source-field" }
quests[6561] = { id = 6561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Villainy", description = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Bashana in Thunder Bluff, {name}, please.", sourceObjective = "Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.", progress = "May the Earthmother be with you, {name}.\n\nPeace between the earth and all her people should be our goal. She has a grand plan for nature, and we all have a role to play in that plan.", completion = "Kelris has eluded the Argent Dawn for some time.\n\nFor some time they considered him dead or missing.\n\nBy ending his reign you have spared the lives of many innocent people, {name}.\n\nEarthmother be praised! To sacrifice another to a servant of an Old God for personal gain is beyond disgusting!\n\nYou have done a great thing this day. Kelris was a creature of evil and sought to bring the world back to a time of chaos by worshipping such creatures as the Old Gods. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6562] = { id = 6562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in the Deeps", description = "Je'neu Sancrea is in need of aid. He waits just inside Blackfathom Deeps in Ashenvale. The Night elf forest is to the north of the Stonetalon mountains. You can reach it by traveling through Windshear Crag or by heading north through Barrens. Zoram Strand is far to the west of the forest. Be careful, {name}. There are forces there that will not take to your presence kindly.", sourceObjective = "Speak to Je'neu Sancrea in Ashenvale.", completion = "Tsunaman sent you? Excellent. Then we have matters to discuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[6563] = { id = 6563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Essence of Aku'Mai", description = "Within the beginning tunnels of Blackfathom Deeps, large sapphire clusters can be found along the cave walls. Recently it was noted that the naga were harvesting the crystals. Until it can be discerned why, I sense we should stop the naga from succeeding. The crystals have great elemental power and if used inappropriately, could make for a powerful arcane component.\n\nWill you help me, {name}? Blackfathom Deeps can be found along Zoram Strand to the north of our outpost.", sourceObjective = "Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale.", progress = "How goes your search for the crystals, {name}? Have you witnessed the naga harvesting them? I pray to my ancestors we find the reason they are collecting such things.", completion = "Well done, {name}. These are the crystals I spoke of. Intriguing...\n\nI can feel the power within them. The spirits of water cling to them. Whatever the naga were going to use these for... well, let us be glad they are no longer in their hands.", sourceObjectiveStatus = "unverified-source-field" }
quests[6564] = { id = 6564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance to the Old Gods", description = "Some poor handwriting is scrawled on the crumpled up note:\n\n\"Yes, tell all the priestesses to bring the crystals to me. The water elemental spirits are strong within them and they will aid our aquamancers greatly in their own summonings.\n\nBy controlling the power within the crystals, we will appease Aku'Mai. One day we will have enough power to bring Aku'Mai back to us and the world will return to its greatest era! An era of rule by the Old Gods!\"", sourceObjective = "Bring the Damp Note to Je'neu Sancrea in Ashenvale.", progress = "Yes, {name}? What is it you need? There is still much I must learn about the crystals the naga are gathering.", completion = "This is interesting indeed. I am glad you have brought it to my attention.\n\nNow we have a name for our troubles... Lorgus Jett.", sourceObjectiveStatus = "unverified-source-field" }
quests[6565] = { id = 6565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance to the Old Gods", description = "This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated. This Lorgus cannot be allowed to succeed. You must stop him, {name}. I cannot do it myself--I am too weak.\n\nGo into Blackfathom Deeps, find him, and kill him. Return to me here.", sourceObjective = "Kill Lorgus Jett.", progress = "Have you found him yet, {name}? Lorgus must be stopped!", completion = "Very good!! Thank you, {name}. We may not have stopped the Twilight's Hammer completely, but at least you have staved off another of their plans to return the Old Gods to power.\n\nWho knows what other plans they have manifesting, but we can rest easy for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[6566] = { id = 6566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Wind Carries", description = "It is good to see you again, {name}. The wind carries with it news from the Eastern Kingdom.\n\nSit, listen.", sourceObjective = "Listen to Thrall.", progress = "Patience, {name}. Pay attention!", completion = "Are you prepared to take on this task?", sourceObjectiveStatus = "unverified-source-field" }
quests[6567] = { id = 6567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion of the Horde", description = "Rexxar, one of my most loyal champions, has discovered a way into the lair of the dragon. However he has left Azeroth to join our expedition into Outland.\n\nHowever, he left his companion, Rokaro, in Shadowprey Village with this information. You are to seek him out.", sourceObjective = "Seek out Rokaro at Shadowprey Village in Desolace.", completion = "There is but one way into the dragon's lair, {race}.\n\nYou see, only the strongest of the Black Dragonflight are allowed entry into the lair of the brood mother. Many trials must be passed and the key to enter ceremoniously enchanted by General Drakkisath himself!\n\nSince you are not of black dragonkin, you may have some difficulty in obtaining passage.", sourceObjectiveStatus = "unverified-source-field" }
quests[6568] = { id = 6568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistress of Deception", description = "Illusion and disguise. That is how you will fool the Black Dragonflight, and gain what you seek.\n\nThough I could teach you something of the skills of deception, you need the help of a master.\n\nI know of one who could do this. In the Western Plaguelands, you will find Myranda the Hag, once a master illusionist of Lordaeron. She has helped us in the past, and if she believes the cause worthy, she may help you.\n\nTake this message to her.", sourceObjective = "Deliver Rokaro's Letter to Myranda the Hag in the Western Plaguelands.", progress = "It is not often I see one of the Horde in these parts of Lordaeron. What is it that you have for Myranda?", completion = "<Myranda holds the note, pauses, then smiles.>\n\nHow is he? Rexxar, I mean. Oh, come now, do not look so confused. The letter was left intentionally blank. It carried with it the intentions and thoughts of its creator. Judging from its contents, it is no wonder Rexxar left it as such. Imagine if you were captured or slain and this information discovered!\n\nOh, nevermind! Myranda will help you, {race}. I owe the Warchief a favor or two.", sourceObjectiveStatus = "unverified-source-field" }
quests[6569] = { id = 6569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oculus Illusions", description = "So the {race} wishes to become one of the Black Flight, eh?\n\nThe creation of the illusion you require is trivial, but the components required for the divination are quite difficult to obtain. The Warchief has entrusted you with this mission, so Myranda must assume you as capable.\n\nTravel to the upper citadel of Blackrock Spire and slay enough of the black dragonspawn to fill up one of your packs with their eyes.\n\nReturn to Myranda when you have gathered enough of the reagent.", sourceObjective = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete.", progress = "The eyes of that which we wish to mimic are the most important ingredient of any illusion, {name}.", completion = "Let Myranda have a look, {race}.\n\nOh yes, these will do nicely.\n\nWith these reagents, Myranda will create for you a medallion that will grant an illusion capable of fooling the black dragonflight's gatekeeper.", sourceObjectiveStatus = "unverified-source-field" }
quests[6570] = { id = 6570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emberstrife", description = "I have attuned this medallion with the magic necessary to create and maintain an illusion within the bounds of the den of Emberstrife.\n\nEmberstrife is an ancient drake; an old gatekeeper of Nefarian, burdened with the duty to test those dragonspawn that would ascend to the rank of elite guard to Onyxia.\n\nTravel to the Wyrmbog of Dustwallow Marsh and enter the lair of Emberstrife. Once there, put on the amulet and follow where your destiny may lead!", sourceObjective = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife.\n\nProvided item:", completion = "Have we run so low on able soldiers that Nefarian is sending me whelps? You will never pass my tests, broodling.", sourceObjectiveStatus = "unverified-source-field" }
quests[6571] = { id = 6571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warsong Supplies", description = "We are in short supply of a few items at the Warsong lumber camp!\n\nPixel at Splintertree Post has our shipment of saw blades. It'll take a trip to Booty Bay to pick up a crate of axes from Wharfmaster Lozgil.\n\nOur shipment of oil and rope will be more difficult. The rope was pilfered by the Thistlefur and Foulweald furbolgs, and the satyrs intercepted the delivery of the oil and are now using it for detestable rituals in Night Run, Satyrnaar, and Xavian!\n\nCan you help me?", sourceObjective = "Collect the Warsong Supplies: Warsong Saw Blades, Logging Rope, Warsong Oil, and the Warsong Axe Shipment for Locke Okarr in Splintertree Post.", progress = "I hope you can come through with the supplies! I'm in big trouble if I don't deliver them soon!", completion = "Excellent, {name}. You've saved me a lot of work!\n\nBut don't think that I'm not grateful!", sourceObjectiveStatus = "unverified-source-field" }
quests[6581] = { id = 6581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warsong Saw Blades", progress = "Direct from Ratchet, the Warsong saw blades! Yep, I have them right here.\n\n..But what sort of payment do you have for me? You can't just take them, you know! My time isn't cheap!\n\nWhat I really need is a good gun to carry with me on my travels. A girl's gotta protect herself, you know? There's a gun I really like that I'm sure an engineer would have no problem making.\n\nSo, if you bring me a deadly blunderbuss, I'll give you the saw blade shipment. Do we have a deal?", completion = "This is perfect -- just the thing! Well, here's the shipment." }
quests[6582] = { id = 6582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Test of Skulls, Scryer", description = "We are Deathwing's children, whelp. Our dominance over the lesser Aspects must be enforced.\n\nIf you are truly worthy of ascension, the lesser dragonflight will wilt in your presence.\n\nFind their champions and lay waste to them in the name of our Father!\n\nTravel to Winterspring and track down the mighty blue drake, Scryer. Crush him and any of the Blue Flight that stand in your path. Tear out his skull and return it to me.", sourceObjective = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.\n\nYou know that Scryer can be found in Winterspring.", progress = "<Emberstrife hisses.>", completion = "One of ssseveral complete...", sourceObjectiveStatus = "unverified-source-field" }
quests[6583] = { id = 6583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Test of Skulls, Somnus", description = "Just as our Father crushes the Aspects themselves, so too must we strive to bring chaos and destruction to their children.\n\nYou must test your battle prowess against the sleepless dreamers: The children of the Green Flight.\n\nTravel to the Swamp of Sorrows and track down Somnus, drake champion of the Green Flight. Let flow your hatred; dominate the insect... Return to me with his skull...", sourceObjective = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife.", progress = "Do not return here until you have bathed in the blood of our enemies and drank in their suffering.", completion = "Another complete...", sourceObjectiveStatus = "unverified-source-field" }
quests[6584] = { id = 6584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Test of Skulls, Chronalis", description = "The time watchers, children of Nozdormu - Lord of the Centuriesss...\n\nIt is three that guard the Caverns of Time, but only one that holds the interests of the Black Flight: The Time Shifter, Chronalis, favored drakeling of Nozdormu.\n\nSsstrike at this champion, a blow to make even the stoic sands of time weep. Return to me with his skull.", sourceObjective = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife.", progress = "Ironically, whelp, time is of the essencccce.", completion = "The most hated remainsss...", sourceObjectiveStatus = "unverified-source-field" }
quests[6585] = { id = 6585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Test of Skulls, Axtroz", description = "It was over the mountains of Grim Batol that our Father raged against the combined might of the Aspects. The cowardly act of the betrayer, Alexstrasza, bought the other Aspects enough time to escape from Father's wrath.\n\nSssuch a shameful act...\n\nThe Red Flight now guards Grim Batol, their lieutenant, Axtroz, must be destroyed. Return the skull of Axtroz to me. For Father, whelp!", sourceObjective = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife.", progress = "Changesss... I sense them taking place in you, whelp. Pass this test and only ceremony remains.", completion = "I had doubted your dedication, whelp. You persisted, dominating our enemies, bringing honor to our flight.\n\nI must now prepare the skulls for your ascension.", sourceObjectiveStatus = "unverified-source-field" }
quests[6601] = { id = 6601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascension...", description = "From the skulls of our enemies is shaped a medallion. You know this medallion, yesss? You have no doubt seen it worn by your elders.\n\nTake it, whelp. Return to the Spire and present it to General Drakkisath. The General will place the final enchantment upon the medallion, attuning the trinket to your spirit.\n\nYou will wear the finished medallion as a badge of honor, symbolizing your ascension to one of our most guarded ranks: Guardian to the brood mother.\n\nGo!", sourceObjective = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rokaro and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next.", progress = "Do not panic, {name}!", completion = "It is merely dragon-talk, {name} - more hot air than actual substantive information. Pompous, aggressive behavior is to be expected from their kind.", sourceObjectiveStatus = "unverified-source-field" }
quests[6602] = { id = 6602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Black Dragon Champion", description = "How would you feel about paying a visit to the General? No illusions, this time.\n\nCeremony? A pretty word to describe the bloodletting that amuses the Black Dragonflight.\n\nAll this amulet requires is the blood of General Drakkisath. Primitive security. There are other ways to receive the General's blood.\n\nGo to Blackrock Spire and kill Drakkisath. Return with his blood and I will activate the key to Onyxia's lair.", sourceObjective = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rokaro.", progress = "Drakkisath is not to be trifled with, {name}. He is responsible for the death of thousands.", completion = "<Rexxar grins.>\n\nThe story of your heroics will be told for years to come, {name}. The Drakefire Amulet is the key to the lair of Onyxia. Gather your forces and conquer in the name of the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[6603] = { id = 6603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in Winterspring!", description = "There's trouble in Winterspring!\n\nWhy, sure, I spend some time out in the wilds and know about these things... I'm always mighty proud to say it. I consider the hours I spend out there in the hills to be golden. Help you cultivate quick reflexes, a cool head and a keen eye...\n\nIt takes judgement, brains and maturity to appreciate the wilderness in the way that I do.\n\nNow, what was I talking about?\n\nAh yes, trouble. See Donova Snowden at the hot springs and she can tell you more.", sourceObjective = "Find Donova Snowden near the hot springs in Winterspring.", completion = "Well, hi there! So Meggi told you of the trouble I have found here?", sourceObjectiveStatus = "unverified-source-field" }
quests[6604] = { id = 6604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged Wildkin", description = "Have you noticed the abandoned camp to the south of here? It looks like the wildkin went crazy and destroyed just about everything they could find!\n\nI heard a rumor that one of the survivors of the attack is resting at Starfall Village, west of here. I'm sure curious about what happened... aren't you?", sourceObjective = "Speak with Jaron Stoneshaper at Starfall Village.", completion = "Aye, what can I do for you?", sourceObjectiveStatus = "unverified-source-field" }
quests[6605] = { id = 6605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange One", description = "I just got back from Felwood, {name}. On my way through, I stopped at Bloodvenom Post and I met a very odd character... She seemed intent on one thing, and I suppose I could tell you what that is, but I think she'd like to explain it to you herself.\n\nIf you're interested, head to Bloodvenom Post in western Felwood and look for Winna Hazzard.\n\nWho knows, she might need your help...", sourceObjective = "Speak with Winna Hazzard in Felwood.", completion = "Ah, {class}. I see that there is hope yet. Are you here to assist me?", sourceObjectiveStatus = "unverified-source-field" }
quests[6606] = { id = 6606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Luck", description = "We can always use a little luck, eh? A small advantage is all it takes to turn things in your favor...\n\nI happened to make the acquaintance of a rather eccentric witch doctor some time back. She made me a lucky charm... for a price. Believe me, though, it was well worth it!\n\nMaybe you'd be interested in one of your own? Find Witch Doctor Mau'ari in Everlook. I'm not giving mine up!", sourceObjective = "Speak with Witch Doctor Mau'ari in Everlook.", sourceObjectiveStatus = "unverified-source-field" }
quests[6607] = { id = 6607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nat Pagle, Angler Extreme", description = "Can't say I really enjoy fishin' much. Figure I been at it for a good 20 or 30 years now.\n\nI reckon people are driven to do what they do for different reasons.\n\nNow, I'm not saying you need to fish for 30 years or catch every fish in the sea to become a master fisherman. I reckon you just need to be determined - determined enough to sit on your duff for hours at a time, doin' nothin'.\n\nI'll tell you what, catch me a few rare fish and I'll teach you a thing or two. Here's a list:", sourceObjective = "Nat Pagle wants you to catch the following fish:\n\nMisty Reed Mahi Mahi from the Misty Reed Strand in the Swamp of Sorrows.\n\nA Sar'theris Striker from the Sar'theris Strand in Desolace.\n\nFeralas Ahi from the Verdantis River of Feralas.\n\nSavage Coast Blue Sailfin from the Savage Coast of Stranglethorn Vale.\n\nReturn to Nat Pagle when you have reeled them all in!", progress = "Anything bitin' today?", completion = "Now that's a fine catch!\n\nCome over here, lemme show you how to set a few lines.", sourceObjectiveStatus = "unverified-source-field" }
quests[6608] = { id = 6608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Too Good.", description = "Lumak no can teach {name} no more. You too good! Find Lumak friend, Nat Pagle. Is human but no eat! Is Lumak friend! Nat teach you fish gooder.\n\nYou find Nat in Dustwallow Marsh, south of Humie town, Thermorosomethinglikedat. Nat probably fishing. Go now!", sourceObjective = "You think Lumak is trying to tell you that he can no longer help you improve your fishing skill. You may want to try to find his friend, Nat Pagle, a human fishing off one of the islands south of Theramore (at least that's what you think Lumak said).", completion = "'Course, you must be a friend of Lumak's.\n\nFishin'? I can tell you all 'bout fishin'.", sourceObjectiveStatus = "unverified-source-field" }
quests[6609] = { id = 6609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Got Nothin' Left!", description = "I'm a dwarf fer cryin' out loud, <lad/missy>! I ain't been designed to fish! I mean look at me! I'm practically made outta stone.\n\nI got nothin' left - ye tapped me out. I've taught ye all I know, flipflop!\n\nDon't ye get it? Ah, fine. I got an ol' friend over on Kalimdor who can help ye out. 'Is name be Nat Pagle, a fine lad. Find him on the islands south o' Theramore. Git goin'!", sourceObjective = "Travel to Kalimdor, to the coastal city of Theramore. From there you must search for an island, south of the main town. Nat Pagle awaits your arrival!", completion = "I've always got room on my island for visitors... I reckon...", sourceObjectiveStatus = "unverified-source-field" }
quests[6610] = { id = 6610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clamlette Surprise", description = "Ever heard of a clamlette? Of course you haven't! It's my latest and greatest culinary masterpiece. Oh, {name}, just thinking about a clamlette makes my mouth water.\n\nUnfortunately, I'm all out of supplies to make any! How about I make you a deal? You gather the supplies I need to make a clamlette and I'll teach you the finer points of exotic cuisine and I'll even throw in a couple of clamlettes to boot! Deal??\n\nHere's what I need:", sourceObjective = "Dirge Quikcleave wants you to get the following items:\n\n10 Giant Eggs. You will find those on the Rocs wandering Tanaris or any other species of large bird.\n\n10 pieces of Zesty Clam Meat. You can find those in clams, naturally!\n\n20 pieces of Fine Aged Cheddar. Get thee to a cheesery!\n\nGather all of the items and return to Dirge.", progress = "My cravings are going to be the end of me! Hurry, {name} - before I dip into my own supply.", completion = "You are in for a special treat, {name}. Watch and learn!", sourceObjectiveStatus = "unverified-source-field" }
quests[6611] = { id = 6611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Gadgetzan You Go!", description = "How you expect Zamja teach you anything? You got all of Zamja's cooking mojo and still you crave more!\n\nZamja can't help. Fat {race} needs to go to Gadgetzan. You find a little goblin named Dirge there - he help you, fatty.\n\nWhen you become big cook on the block, you come back and teach Zamja, ok? Now go!", sourceObjective = "Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.", completion = "<Dirge spits out some leather sandal bits.>\n\nPfftooey...\n\n<Dirge hacks loudly.>\n\nWhat? I'll have you know that leather is surprisingly high in protein and low in carbohydrates.", sourceObjectiveStatus = "unverified-source-field" }
quests[6612] = { id = 6612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Know A Guy...", description = "I can tell by yer cooking spoon that ye know what yer doin'. Unfortunately, I can't teach ya nothin'.\n\nLuckily fer ye, I know a guy. He's a goblin and probably the best cook on Kalimdor.\n\nAyep, that's the bad news, <lad/missy> - ye got to travel to Kalimdor. Git to Gadgetzan and find Dirge Quikcleave. He'll set ya straight.", sourceObjective = "Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.", completion = "<Dirge spits out leather.>\n\nPfftey...\n\n<Dirge hacks loudly.>\n\nWhat? I'll have you know that leather is surprisingly high in protein and low in carbohydrates, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6621] = { id = 6621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Foulweald", description = "My research has paid off.\n\nI believe that with a show of force, we can diminish the furbolgs' aggressiveness.\n\nTake this banner a short ways northeast and place it on their totem mound. They will try to destroy the banner, but hold your ground until their chief, Murgut, appears to save face for the tribe.  Bring me the totem he carries.\n\nGather your allies, {name}. This is no task for a single {class}.", sourceObjective = "Place Senani's Banner on the Foulweald Totem Mound. Do not let the furbolgs destroy the banner. Defeat Chief Murgut and bring Murgut's Totem to Senani at Silverwind Refuge.", progress = "Did you defeat Chief Murgut, {name}?  Did you retrieve his Foulweald Totem?", completion = "Good work, {name}.  Issuing that challenge to the Foulwealds and defeating their leader sends them a strong message:\n\nThe Horde is not to be trifled with.\n\nI don't believe that tribe will be giving us much trouble for a long time.", sourceObjectiveStatus = "unverified-source-field" }
quests[6622] = { id = 6622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triage", description = "Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Horde Trauma.\n\nNow pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage.\n\nTriage bandages will be supplied.\n\nGood luck, doctor.", sourceObjective = "Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.\n\nRemember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.", progress = "Miraculous work, doctor. Simply miraculous.", completion = "Doctor {name}, welcome to Horde Trauma.", sourceObjectiveStatus = "unverified-source-field" }
quests[6623] = { id = 6623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horde Trauma", description = "Doctor {name}, I presume. It is a pleasure to see you again.\n\nI have some wonderful news for you! Doctor Gregory Victor, chief physician of Horde Trauma has made a personal request for you to join him at Hammerfall. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great Doctor Gregory Victor! Do not squander this opportunity!", sourceObjective = "Travel to Hammerfall in the Arathi Highlands and speak with Doctor Gregory Victor about joining the ranks of Horde Trauma.", completion = "Wonderful. Put on your scrubs, we are to start at once!", sourceObjectiveStatus = "unverified-source-field" }
quests[6624] = { id = 6624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triage", description = "Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Alliance Trauma.\n\nNow pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage.\n\nGood luck, doctor.", sourceObjective = "Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.\n\nRemember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.", progress = "Miraculous work, doctor. Simply miraculous.", completion = "Doctor {name}, welcome to Alliance Trauma.", sourceObjectiveStatus = "unverified-source-field" }
quests[6625] = { id = 6625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance Trauma", description = "Doctor {name}, I presume. It is a pleasure to see you.\n\nI have some wonderful news for you! Gustaf VanHowzen, chief physician of Alliance Trauma has made a personal request for you to join him at Theramore. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great doctor, Gustaf VanHowzen! Do not squander this opportunity, doctor!", sourceObjective = "Travel to Theramore in the Dustwallow Marsh and speak with Doctor Gustaf VanHowzen about joining the ranks of Alliance Trauma.", completion = "Wonderful. Put on your scrubs, we are to start at once!", sourceObjectiveStatus = "unverified-source-field" }
quests[6626] = { id = 6626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Host of Evil", description = "The Forsaken do not pass on their... illness... from what I have seen. This diplomat seems to be granting undeath to would-be followers. I am beginning to think he is one of the Scourge.\n\nFor now, my concern is not with him though, it's with the growing ranks around him. They creep from the shadows daily, almost begging him for more power.\n\nI'm not powerful enough to fight them on my own, {name}. What do you say? Are you up for some hunting?", sourceObjective = "Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.", progress = "How goes the hunt, {name}? Seeing just this small sample of this diplomat's power here removes any doubt I had that the Scourge are one of the greatest threats this world has ever seen.", completion = "Thank you, {name}! The work you've done will be a great help, I'm sure.\n\nI will continue my study of this diplomat and the rest of the quilboar here. If you seek greater adventure, I'd find a few friends and head into the cave that looks like a great boar maw just over there. I'm sure once you're inside you'll find greater challenges to face.", sourceObjectiveStatus = "unverified-source-field" }
quests[6627] = { id = 6627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Lore", description = "You have brought me the book, and now it is time for your question. Are you ready?\n\nTime is not an issue, {class}, so do not feel pressured. You may take as long as you like to answer.", sourceObjective = "Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready.", progress = "Life is full of questions, {class}. You will never be able to answer all of them, but with some time and study, perhaps you will become a little more knowledgeable.", completion = "Well done, {class}. You have studied the text I asked you to, and now you have passed another of our tests.", sourceObjectiveStatus = "unverified-source-field" }
quests[6628] = { id = 6628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Lore", description = "So the time is once again upon us. As a student of lore, you have shown great tenacity by undertaking my task.\n\nAnd so now I offer you your question. If you are ready, speak to me again, and take all the time you need, {name}--there is no pressure to answer quickly.", sourceObjective = "Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready.", progress = "There is only one rule I feel you must know if you wish to survive in this world: the more you know, the more you'll see.\n\nIf you study, if you observe, then you will begin to see things in the world that no other {race} will see.", completion = "Well done, {name}. I had my doubts if you studied the text I asked you to get, but you've answered correctly.", sourceObjectiveStatus = "unverified-source-field" }
quests[6629] = { id = 6629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Grundig Darkcloud", description = "{name}, you've done a fine job killing Grimtotem. If you dare, Grundig Darkcloud and his personal band of brutes is by far the worst of the lot. He was the one who led the brutal attack on my village.\n\nYou will find him in Grimtotem Post a bit further up the path to the west. Kill him, and I will be forever grateful.", sourceObjective = "Kill Grundig Darkcloud and 6 Grimtotem Brutes, and return to Makaba Flathoof near the southeastern edge of Stonetalon.", progress = "Have you killed Grundig Darkcloud and his personal band of Brutes?", completion = "Grundig Darkcloud is dead! {name}, I will always be grateful for what you've done here today.", sourceObjectiveStatus = "unverified-source-field" }
quests[6641] = { id = 6641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsha the Lasher", description = "Vorsha the Lasher... the fiendish hydra that roams the seas...\n\nShe has attacked our outpost, each time unprovoked, laying waste to anything that falls in her path.\n\nBut I am ready, {name}. I have prepared to best the hydra and end these attacks on Zoram'gar.\n\nThe naga honor the wicked nature of this beast with a brazier that remains lit on an island just off the coast. I believe that if we put it out, Vorsha will appear in anger.\n\nWe will need help, so be sure to bring some strong allies.", sourceObjective = "Defeat Vorsha the Lasher.", completion = "I have witnessed many naga attacks since I arrived here. It puts my mind at ease that Vorsha will no longer roam freely.\n\nWe are in your debt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6642] = { id = 6642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor Amongst the Brotherhood, Dark Iron Ore", progress = "Dark Iron, while plentiful in the Depths, is still a valued commodity amongst the Brotherhood. The sacred arms and armaments of Ragnaros favor Dark Iron.\n\nFor every 10 pieces of Dark Iron Ore you offer, favor amongst the Brotherhood you will gain.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades." }
quests[6643] = { id = 6643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor Amongst the Brotherhood, Fiery Core", progress = "Woe unto those that tempt fate inside the Molten Core. Death comes swiftly - the punishment dealt without mercy.\n\nMany of the Brotherhood have been lost in their search for Fiery Cores.\n\nOffer 1 Fiery Core and you shall be granted favor amongst the Brotherhood.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades." }
quests[6644] = { id = 6644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor Amongst the Brotherhood, Lava Core", progress = "The Thorium Brotherhood sympathizes with your plight, {race}. This is why Lokthos has been empowered to bargain.\n\nOffer 1 Lava Core and you shall be granted favor amongst the Brotherhood.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades." }
quests[6645] = { id = 6645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor Amongst the Brotherhood, Core Leather", progress = "Many of the sacred recipes require the skin from Ragnaros' chosen pets.\n\nOffer 2 Core Leather, skinned from the smoldering corpses of the Core Hounds of the Molten Core and you shall be granted favor amongst the Brotherhood.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades." }
quests[6646] = { id = 6646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor Amongst the Brotherhood, Blood of the Mountain", progress = "The tears of the Fire Lord are a rare find indeed.\n\nOffer 1 Blood of the Mountain and you shall be granted favor amongst the Brotherhood.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades." }
quests[6661] = { id = 6661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deeprun Rat Roundup", description = "Avast ye scallywag. Arrrr... Arrrr ye looking fer work? We gots a serious rat problem down here an' not enough hands on the poop deck.\n\nWhat do ye say? All ye needs to do is take this here rat catchin' flute and play the melody around the vermin. They'll follow ye to the ends of the world!\n\nJust capture five of the little buggers and bring em back here. We needs em alive.\n\nArrrrr...", sourceObjective = "Capture 5 Deeprun Rats by using the Rat Catcher's Flute. Lead the rats back to Monty.", progress = "Yarrr... Swabby, what be takin' ye so long?", completion = "These'll werk nicely, matey. Me brother needs em still tickin' and kickin,' else they go sour... Ye don't want to taste no sour rat kabob.", sourceObjectiveStatus = "unverified-source-field" }
quests[6662] = { id = 6662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Me Brother, Nipsy", description = "Me brother, Nipsy, runs a rat kabob operation on the other side of Deeprun. Ye needs to take this here crate o' rats to him before they go bad. Get a move on!\n\nYe have ridden a tram before, aye? It's easy. Just step aboard when she arrives and enjoy the ride. An' keep yer arms and legs inside durin' the ride, lest ye be peglegged fer life.", sourceObjective = "Take the Carton of Mystery Meat to Nipsy at the Stormwind Deeprun Tram Depot.", progress = "<Nipsy puts his index finger through one of the air holes in the carton.>\n\nAlive and kicking... and just in time!", completion = "Poor Monty. Ever since the Gnomeregan incident, he hasn't been the same. That boy has never seen an ocean in his life, let alone being some kind of pirate.\n\n<Nipsy sighs.>\n\nAt least he keeps the flow of twitching critters coming.", sourceObjectiveStatus = "unverified-source-field" }
quests[6681] = { id = 6681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Manor, Ravenholdt", description = "{name},\n\nRavenholdt has taken an interest in you, young thief. We have been watching. Your style is a bit awkward but nothing we couldn't fix.\n\nShould you be prepared to embark on a career as a disciple of Master Ravenholdt and member of the Assassin's League, you have only to bring the Seal of Ravenholdt (attached to this letter) to Ravenholdt Manor.\n\nYour first task is to find the manor, hidden away in the hills of Hillsbrad and demonstrate your cunning.\n\nRegards,\n\nFahrad", sourceObjective = "Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\n\nYour cunning will be tested along the way. Be prepared.", progress = "Did you meet Milton?\n\n<Fahrad laughs.>", completion = "Most excellent, young thief.\n\nYou look a bit beaten down, but no worse for the wear.\n\nA long journey awaits you - long and rewarding. Are you prepared to finally embrace your destiny among the masters of Ravenholdt?\n\nSpeak with the guards outside. They will get you started.", sourceObjectiveStatus = "unverified-source-field" }
quests[6701] = { id = 6701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Syndicate Emblems", progress = "We have been entrenched in a battle with the Syndicate for years. What they lack in skill they make up for in numbers. It's impossible to kill them off fast enough to have any noticeable impact on their population!\n\nWe've found that the best way to deal with their size is to pilfer their emblems. Once an emblem is stolen the shamed member is 'dealt' with internally.\n\nPick their pockets clean and turn the emblems in to me or one of the other guards.\n\nStart at Durnholde, south of here.", completion = "Hey, nice work! Keep this up and the other rogues might stop spitting on you." }
quests[6721] = { id = 6721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.", sourceObjective = "Speak with Dazalar at Dolanaar in Teldrassil.", completion = "Yes, it is time to train you...", sourceObjectiveStatus = "unverified-source-field" }
quests[6722] = { id = 6722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.", sourceObjective = "Speak with Dazalar at Dolanaar in Teldrassil.", completion = "Yes, it is time to train you...", sourceObjectiveStatus = "unverified-source-field" }
quests[6741] = { id = 6741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Booty!", progress = "I need more armor scraps, {name}!  Do you have any?", completion = "Thanks again, {name}.  You do the Horde proud..." }
quests[6761] = { id = 6761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Frontier", description = "I have relegated my second, Mathrengyl Bearwalker, to deal with Moonglade's call for aid.  Speak to him on this matter - NOT me.\n\nLet me give you some... friendly... advice.  It is I who led us out of the darkness - NOT the Cenarion Circle in Moonglade - when all was lost for our race.  Teldrassil gives us all new life!  They would have you believe otherwise, and to believe their propaganda would be a fool's task.\n\nI'll leave it to you to decide whether or not you're a fool.", sourceObjective = "Speak with Mathrengyl Bearwalker at the Cenarion Enclave of Darnassus.", completion = "Yes {class}, thank you for coming.  I apologize about the misunderstanding... the air is thick with mistrust between the Arch Druid here and Keeper Remulos in Moonglade.  Each suspect the other of chicanery, and the fact that strange corruptions of Teldrassil continue unabated are still an issue here.  It does little to quell mistrust.\n\nRegardless, our duty to the Cenarion Circle remains... even if those who lead it may disagree with one another.", sourceObjectiveStatus = "unverified-source-field" }
quests[6762] = { id = 6762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabine Saturna", description = "For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris... and even further west of Un'Goro.  You should find him in Nighthaven, the main village of Moonglade.\n\nWhile your work will no doubt be of tremendous benefit to us all, I advise you to tread gingerly.  There are tensions between Darnassus and Moonglade... ones that may grow over the course of time.", sourceObjective = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade. Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.", completion = "I am Rabine Saturna, and on behalf of Keeper Remulos and all of the denizens of this sacred glade I bid you welcome.\n\nI appreciate your interest and eagerness to assist the Cenarion Circle.  I also know that Arch Druid of Darnassus expressed his displeasure to you in your lending us aid.  Rest assured that it is for the greater good, and that you will be safe from any ill-conceived repercussions you may be the target of.\n\nYou are among friends here, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6781] = { id = 6781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Armor Scraps", progress = "{name}, we need more armor scraps to supply our troops!", completion = "These are some good pieces, {name}.  I can use them to fashion new equipment for our troops.\n\nIf my supply level gets high enough, then maybe our seasoned fighting units will enter the field!" }
quests[6801] = { id = 6801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokholar the Ice Lord", progress = "I come from Thunder Bluff, {race}. Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times.\n\nBut let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin.\n\nVictory will be assured when the elemental lord is loosed upon the Stormpike army.", completion = "The blood of our enemies has been shed. I shall mix this blood with the rest that has been gathered. Once the offering is complete, the Ice Lord shall show these Stormpike dogs the full wrath of the Frostwolf Clan!" }
quests[6804] = { id = 6804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poisoned Water", description = "A force of elemental scouts was sent to the eastern plaguelands of Lordaeron, and the disease of that place twisted and infected them.  The Waterlords cannot allow this affront to our purity!\n\nTake this vial.  In it is a quantity of one aspect of Neptulon.  If used on the plagued elementals it will fight the poison within their bodies and cure them!  But their inner conflict will drive them into a surging madness.\n\nDefeat the discordant surges and bring me their bracers of binding.", sourceObjective = "Use the Aspect of Neptulon on poisoned elementals of Eastern Plaguelands. Bring 12 Discordant Bracers and the Aspect of Neptulon to Duke Hydraxis in Azshara.", progress = "Do you have the bracers?", completion = "You have done well, {class}.  The corrupted elementals you cured were an outrage to all bodies of water.  Our strength lies in our purity and if we are to win our war with the others, we must remain strong.", sourceObjectiveStatus = "unverified-source-field" }
quests[6805] = { id = 6805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormers and Rumblers", description = "We, the elementals of water, wage war with those beings of the lesser elements.  If you are truly our ally in this conflict, then show me your conviction!\n\nFar to the south, in the desert land of Silithus, the servants of air and earth scurry in a corner of rock named the Crystal Vale.  They protect items of power from smaller beings, mortals, and although I do not know why they do this, I wish to foil their efforts.\n\nGo to the Crystal Vale in Silithus and defeat our enemies, then return to me.", sourceObjective = "Kill 15 Dust Stormers and 15 Desert Rumblers and then return to Duke Hydraxis in Azshara.", progress = "Cowardice is not a thing we hold in regard, {class}.  Go to Silithus and prove your bravery.", completion = "Your bravery is proven, as is your worth to us.  Perhaps I may have future tasks for you, tasks more befitting a valued ally of the Waterlords.", sourceObjectiveStatus = "unverified-source-field" }
quests[6821] = { id = 6821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of the Emberseer", description = "You have shown me that you can defeat our enemies and perform missions to further the cause of the Waterlords.  But until now you have only faced lesser foes... if pitted against a powerful enemy, can you prevail?\n\nThat is your new task.\n\nHigh up in Blackrock Spire the orcs have captured a servant of fire, the Pyroguard Emberseer.  Find his place of imprisonment, slay his captors, and then slay the emberseer.  Bring me his eye and it will show me your worth.", sourceObjective = "Bring the Eye of the Emberseer to Duke Hydraxis in Azshara.", progress = "Do you have the Eye, {class}?  Do you have the strength to enter Blackrock Spire?", completion = "Ah, so you do have the strength.  And you have the cunning as well, for Blackrock Spire is more than a match for brute strength alone.\n\nIndeed {name}, you may yet prove a valued ally to us...", sourceObjectiveStatus = "unverified-source-field" }
quests[6822] = { id = 6822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Molten Core", description = "{name}, perhaps it is time to give you a real test.  Are you ready?\n\nAt the bottom of Blackrock Depths is a passage to the Molten Core.  This is a stronghold of our enemy, held by the most powerful servants of fire on this world.\n\nGo to the Molten Core, {name}.  Show me you have the strength and the will to defeat what you find there.\n\nAnd if you have allies among your people, then rally them.  Nothing short of an army can hope to enter the Molten Core and live.", sourceObjective = "Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara.", completion = "You have done what most of your kind would think impossible.  You have faced the beings of the Molten Core, and triumphed!\n\nFor so small a creature, you have displayed great resource.\n\nSome day, perhaps we might strike a true allegiance between your kind and the Waterlords.", sourceObjectiveStatus = "unverified-source-field" }
quests[6823] = { id = 6823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agent of Hydraxis", description = "If you truly wish an allegiance with us, then I invite you to wage war on our foes, the servants of air and earth and fire.  Each defeat you heap upon them will weaken their foothold here, and further prove your adherence to our cause.\n\nThe campaign will be long, but if you persevere then your glory and honor will be great.", sourceObjective = "Earn an Honored faction with the Hydraxian Waterlords, then talk to Duke Hydraxis in Azshara.", progress = "Your campaign is not yet done, {name}.  Go out and defeat our enemies, the servants of air and earth and fire, and one day perhaps you will earn a place in the hall of the Waterlords.", completion = "Your exploits against our enemies ring through the chambers of the Waterlords, {name}.  It was thought by some that your form is too small and fragile to fight in our war, but you have made great gains.  You have earned respect among us, an unbelievable feat.", sourceObjectiveStatus = "unverified-source-field" }
quests[6824] = { id = 6824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hands of the Enemy", description = "{name}, your service is of great value to us, so we are reluctant to send you on this last mission for we do not want to lose such a useful agent.\n\nBut its success would further our war efforts tremendously and... it was deemed worth risking you.\n\nWe want these captains in the Molten Core destroyed: Lucifron, Sulfuron, Gehennas and Shazzrah.  Kill them and bring me their hands!\n\nThis task will take every resource you possess, {name}, but if can do it then the Firelords will be dealt a terrible blow.", sourceObjective = "Bring the Hands of Lucifron, Sulfuron, Gehennas and Shazzrah to Duke Hydraxis in Azshara.", progress = "Have you defeated Lucifron and the others, {name}?  Do you have the hands of the enemy?", completion = "You have the hands!  You defeated the fire captains!  I would not have thought it possible, had I not known you and what you are capable of.\n\n{name}, your exploits are without number, but word of this last feat will send waves among the Waterlords.  Your name may one day be legend to us.\n\nSpeak with me again, {name}.  I may have yet another task...", sourceObjectiveStatus = "unverified-source-field" }
quests[6825] = { id = 6825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air - Guse's Fleet", progress = "We must prepare the new fleet of War Riders, {race}! My riders are set to make a strike on the central battlefield; but first, I must wet their appetites - preparing them for the assault.\n\nI need enough Stormpike Soldier Flesh to feed a fleet! Hundreds of pounds! Surely you can handle that, yes? Get going!", completion = "The fleet feeds on their flesh. It consumes the enemy.\n\nFlight is imminent!" }
quests[6826] = { id = 6826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air - Jeztor's Fleet", progress = "You've worked hard, {name}, but we have only just begun!\n\nMy War Riders must taste in the flesh of their targets. This will ensure a surgical strike against our enemies!\n\nMy fleet is the second most powerful in our air command. Thusly, they will strike at the more powerful of our adversaries. For this, then, they need the flesh of the Stormpike Lieutenants.\n\nMake haste, soldier!", completion = "More! More! Bring more for they are soon to be ready!" }
quests[6827] = { id = 6827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air - Mulverick's Fleet", progress = "I was locked up in a dwarven hellhole for days. You better believe I want revenge!\n\nWe must plan carefully.\n\nFirst, my war riders need targets to gun for - high priority targets. I'm going to need to feed them the flesh of Stormpike Commanders. Unfortunately, those little buggers are entrenched deep behind enemy lines! You've definitely got your work cut out for you.", completion = "Not enough! I would expect this level of work from an initiate, but you, {name}? Come on, soldier! HUSTLE! More flesh is needed!" }
quests[6844] = { id = 6844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umber, Archivist", description = "There's plenty to do here still, but I think taking this back to the Circle for analysis is key.  Trust me - the work will still be here once this is all said and done.  If it's a journal inside this sticky chitin, then the Circle would finally have a window into the past!\n\nTake this to the Circle's archivist in Nighthaven.  His name is Umber, and the man's brilliant.  Touched, sure, but brilliant nonetheless!  Umber's salvaged tomes in far worse shape than this.  If it can be saved, he can do it.", sourceObjective = "Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade.", progress = "Why, hello there!  Hrmm...\n\nLet me be a little honest with you, friend... you smell a bit ripe.  Whiffy, one might say.  Now I'm not making a personal assailment of your being.  I'm just saying... in the future, you may want to freshen up a little after coming in from the field.  It will make those first impressions a little more positively impressionable!\n\nAnyhoo... what can I do for you?", completion = "Well great monkey toads!  What have you got here?  It's sort of book shaped, I guess... I'll try and crack this shell on it.\n\nLayo sent you to me from Silithus?  I've only heard very hushed rumblings - which I guess aren't all that hushed when you think about it - about the horrors that are going on out there.  Couple that with my lack of pleasure for anything bug-like, and you've got the recipe for me needing to stay here with the books!", sourceObjectiveStatus = "unverified-source-field" }
quests[6845] = { id = 6845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncovering Past Secrets", description = "Anyway, you should check back with me relatively soon... that is if you want to know what was in here.  As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you.\n\nIn the meantime, I'd check in with the den mother of this little bear camp, Rabine.  No doubt he'll want to know what crazy antics you've been up to.  Never leave the den mother waiting, {name}... that is, unless you want to be doused in honey.\n\nIt's happened, trust me.", sourceObjective = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.", completion = "Ah, {name} - I had hoped you would stop by.  I am glad to see you well.\n\nI received notice you would be coming in from the field, and I wanted to personally express the Cenarion Circle's gratitude for the assistance you've given us thus far.  No doubt there are more secrets to uncover from Silithus; your delivery to Umber should prove most interesting once uncovered.  Please, accept this as a token of our continued appreciation for your aid.\n\nThank you, generous {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6846] = { id = 6846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begin the Attack!" }
quests[6847] = { id = 6847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master Ryson's All Seeing Eye", description = "Your war in the heart of Alterac means nothing to the Syndicate, {class}. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.\n\nThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.\n\nRecover the Eye and our services shall be yours - for whatever time remains for your side.\n\nReturn to me once you acquire the eye so that I may examine you.\n\n<Master Ryson grins.>", sourceObjective = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\n\nBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", sourceObjectiveStatus = "unverified-source-field" }
quests[6848] = { id = 6848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master Ryson's All Seeing Eye", description = "Your war in the heart of Alterac means nothing to the Syndicate, {class}. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.\n\nThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.\n\nRecover the Eye and our services shall be yours - for whatever time remains for your side.\n\nReturn to me once you acquire the eye so that I may examine you.\n\n<Master Ryson grins.>", sourceObjective = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\n\nBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", sourceObjectiveStatus = "unverified-source-field" }
quests[6861] = { id = 6861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinfizzlex's Portable Shredder Unit", description = "I'm as anxious as you are to try out my portable shredder unit, {race}, but before I can make the kit, I'm going to need materials - lots of materials!\n\nTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.\n\nWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Stormpike lumber camp.", sourceObjective = "Master Engineer Zinfizzlex wants you to bring him the following:\n\n*30 Thorium Bars.\n\n*50 Mithril Bars.\n\n*75 Iron bars.\n\n*1 Steamsaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[6862] = { id = 6862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinfizzlex's Portable Shredder Unit", description = "I'm as anxious as you are to try out my portable shredder unit, {race}, but before I can make the kit, I'm going to need materials - lots of materials!\n\nTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.\n\nWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Frostwolf lumber camp.", sourceObjective = "Master Engineer Zinfizzlex wants you to bring him the following:\n\n*30 Thorium Bars.\n\n*50 Mithril Bars.\n\n*75 Iron bars.\n\n*1 Steamsaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[6881] = { id = 6881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ivus the Forest Lord", progress = "The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked.\n\nThe damage has grown too great for the Circle to control! Ivus must be called to our aid.\n\nThe Frostwolf soldiers carry elemental charms called storm crystals. We can use the charms to conjure Ivus. Venture forth and claim the crystals, {name}!", completion = "Well done, {name}. I will use the power of this charm to augment the magic that has already been gathered. When enough power has been amassed, I shall focus the collected energies and call upon the Forest Lord to aid our cause." }
quests[6901] = { id = 6901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Launch the Attack!" }
quests[6921] = { id = 6921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amongst the Ruins", description = "The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good.\n\n{name}, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop them!", sourceObjective = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", progress = "Have you been successful in locating the fathom core?  Without it we'll have no idea what the Twilight's Hammer is exactly up to down there.", completion = "This is exactly what I need!  A fathom core is an incredible well of information that we will be able to draw much good from.  Whatever the Twilight's Hammer is up to in there - and believe me when I say it is no good - my comrades and I will now uncover.\n\nYou've done well here today; the Earthen Ring looks upon you warmly for assisting us.  You've also helped the Horde as a whole, and for that you should be proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[6922] = { id = 6922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Aquanis", description = "The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.\n\nIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.", sourceObjective = "Bring the Strange Water Globe to Je'neu Sancrea in Blackfathom Deeps.", progress = "Ah, hello again {name}.  I was just reading the waves the sea, much like I always do.  What brings you to the outpost?", completion = "This... this is quite the find, {name}.\n\nYou acquired this from Baron Aquanis in Blackfathom, you say?  Baron Aquanis has long been thought of as a corrupted elemental power; this globe will prove what exactly had corrupted him.  While it would be no surprise if it turned out to be the Twilight's Hammer, our studies will also show how they did it as well.\n\nYou did well in bringing this to me.  Please - take this, along with the Earthen Ring's warmest regards.", sourceObjectiveStatus = "unverified-source-field" }
quests[6941] = { id = 6941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air - Vipore's Fleet", progress = "The elite Frostwolf units that guard the lines must be dealt with, soldier! I'm tasking you with thinning out that herd of savages. Return to me with medals from their lieutenants and legionnaires. When I feel that enough of the riff-raff has been dealt with, I'll deploy the air strike.", completion = "The flight will be ready soon. Continue your efforts!" }
quests[6942] = { id = 6942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air - Slidore's Fleet", progress = "My gryphons are poised to strike at the front lines but cannot make the attack until the lines are thinned out.\n\nThe Frostwolf warriors charged with holding the front lines wear medals of service proudly upon their chests. Rip those medals off their rotten corpses and bring them back here.\n\nOnce the front line is sufficiently thinned out, I will make the call to air! Death from above!", completion = "Keep em coming, soldier! The Aerie gryphons will be ready to strike in no time at all!" }
quests[6943] = { id = 6943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air - Ichman's Fleet", progress = "Their spirits are low, soldier. After our last failed air strike against the Horde, they refuse to fly! It is up to you to bolster their morale.\n\nReturn to the battlefield and strike at the heart of the Frostwolf's command. Take down their commanders and guardians. Return to me with as many of their medals as you can stuff in your pack! I promise you, when my gryphons see the bounty and smell the blood of our enemies, they will fly again! Go now!", completion = "Can you see it? Look at them, soldier! They're coming around... Soon, Ichman's flight will once again strike at the heart of the valley! Stormpike will rule the skies!" }
quests[6961] = { id = 6961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Great-father Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Great-father Winter!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", sourceObjective = "Speak with Great-father Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.", completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah.", sourceObjectiveStatus = "unverified-source-field" }
quests[6962] = { id = 6962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treats for Great-father Winter", description = "Hey, can you do Great-father Winter a favor, um, little <boy/girl>?\n\nNot to needlessly talk about myself in the third person, but Great-father Winter has been at this all day and he could use a treat himself.  Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot.  Think you could be a friend to the Great-father and fetch some for me?", sourceObjective = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Great-father Winter in Orgrimmar.", progress = "All this talk of treats has given me a hankering for some myself.  Mmmm... gingerbread cookies and milk...", completion = "You're quite the helper to ol' Greatfather Winter there, {name}.  Have a great Feast of Winter Veil.\n\nHere's a little something... you know, for the effort.", sourceObjectiveStatus = "unverified-source-field" }
quests[6963] = { id = 6963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Winter Veil Treats", description = "Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.\n\nWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains area of Hillsbrad Foothills, and that's where our man went.\n\nSee if both are out there, safe and sound!", sourceObjective = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Hillsbrad Foothills.", completion = "Y-y-you can h-h-hear me!  Thank the b-b-bottom line!\n\nI'm not really a s-s-snowman - my n-n-name is Sacks, and I w-w-work for the Orgrimmar b-b-branch of Smokywood Pastures... I g-g-got sent out here to look for a m-m-missing package, when I was attacked by a c-c-creature I have never seen b-b-before!\n\nSo v-v-very cold...", sourceObjectiveStatus = "unverified-source-field" }
quests[6964] = { id = 6964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reason for the Season", description = "Gifts, treats, presents... bah, I say!\n\nThose goblins pollute the true meaning of this season - the Feast of Winter Veil.  This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit!\n\nIf you're interested in learning what the Feast is all about for yourself, ask Sagorne Creststrider.  I'm sure he'll be surprised that someone cares about history rather than getting presents.", sourceObjective = "Speak with Sagorne Creststrider in the Valley of Wisdom of Orgrimmar about the Feast of Winter Veil.", completion = "The Feast of Winter Veil, you say?  Alas, in times past it held a more substantial meaning to us tauren.  Nowadays, it seems as though others have turned the legend of this season of renewal into something that helps to sell candies and presents.\n\nIt's no surprise that Furmund is bitter about that sort of change.  He and other tauren like him cling to our past like a banner of war.  While I think a little celebration is always good, it is important to remember the origins of the Feast.", sourceObjectiveStatus = "unverified-source-field" }
quests[6981] = { id = 6981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Glowing Shard", description = "The shard is a brilliant green, and although solid, what looks like smoke swirls just below the surface. You can't help staring into the depths of the crystal; at the same time, you know there is something very disturbing about it.\n\nMaybe you should see if anyone in Ratchet can tell you more about this strange shard.", sourceObjective = "Travel to Ratchet to find someone that can tell you more about the glowing shard.\n\nThen, deliver the shard as you are directed.", progress = "Hello, {race}. What can I do for you?", completion = "Oh... I have never seen anything like this...", sourceObjectiveStatus = "unverified-source-field" }
quests[6982] = { id = 6982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coldtooth Supplies", description = "The Coldtooth mine is a storage depot for the Horde.  I can't stomach the food they give their troops, and the state of their arms and armor is atrocious!  But... in times like these when supplies are so important, we can use what they have.\n\nEnter the Coldtooth mine and bring me back their supplies.  That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde's warriors.\n\nGood luck, {name}.  The mine is to the distant south, deep in Horde territory.", sourceObjective = "Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar.", progress = "Did you enter the Coldtooth mine in Horde territory, {name}?  Did you raid their supplies?", completion = "You got them!  Well done, {name}!  I'll go through these supplies and get them ready for our own troops!", sourceObjectiveStatus = "unverified-source-field" }
quests[6983] = { id = 6983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're a Mean One...", description = "A creature called \"The Abominable Greench\" stole our shipment of treats, {name}.  Be careful though!  He's vicious and a bunch of those little green gnomes do his bidding!\n\nYou're gonna need some help in facing him.  Rumor has it he's holding our treats and our beloved Metzen the Reindeer at Growless Cave in the Hillsbrad Foothills!  Find the treats {name} and bring them back before the celebration is ruined and all the children of Ogrimmar are disappointed!", sourceObjective = "Recover the Stolen Treats and free Metzen the Reindeer after defeating the Abominable Greench, who is hiding out near Growless Cave in the Hillsbrad Foothills.", progress = "{name} - our Feast of Winter Veil will be ruined without those treats to restock!  Graccu himself will miss out on sharing his delicious meat pies with all the good boys and girls this season...", completion = "You found it!  You've saved Smokywood Pasture's Feast of Winter Veil!\n\nPoor Sacks... we'll be sure to send a team out there and figure out a way to unfreeze him.  Hopefully, he'll be back in time for the day of the Feast; he'll need to make up missed time working though.  Still, this wouldn't even be possible if it weren't for you!", sourceObjectiveStatus = "unverified-source-field" }
quests[6984] = { id = 6984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Smokywood Pastures' Thank You!", description = "We at Smokywood Pastures appreciate the recovery of the stolen treats, {name}.  For that, we'd like to offer you a special gift... presented by none other than Great-father Winter himself!\n\nPlease, speak with Great-father Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!", sourceObjective = "Speak with Great-father Winter in Orgrimmar.", completion = "Ho ho hello, adventurer!\n\nThe goblins told me that you have earned a special gift this holiday season, and I am pleased to give it to you.  Here you go - have a wondrous Feast of Winter Veil this and every season in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[6985] = { id = 6985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irondeep Supplies", description = "The Stormpike dwarves are using the Irondeep mine as a storage depot.  I want you to raid that mine and bring me its supplies.  This will curtail the Stormpikes' efforts in Alterac Valley, and will provide us with needed equipment!\n\nBe wary, {name}.  The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.", sourceObjective = "Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep.", progress = "Did you enter the Irondeep mine, {name}?  Did you raid its supplies?", completion = "You got them!  Nicely done, {name}!  And I hope you saw a few dwarves during your raid, and shed their blood for the Frostwolves!", sourceObjectiveStatus = "unverified-source-field" }
quests[7001] = { id = 7001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empty Stables", description = "The war in the valley has taken its toll on our soldiers. We must revitalize our forces!\n\nIf we can fill up the stables, the Wolf Riders will once more be able to ride out into the field of battle.\n\nTake this muzzle and track down the frostwolves that inhabit the nearby forest. Once you find a wolf, use the muzzle to tame the beast. Bring the tamed beast back to me so that I may place it in the stable.\n\nWhen we have enough wolves stabled, the Wolf Riders will rejoin their patrol on our front lines.", sourceObjective = "Locate a Frostwolf in Alterac Valley. Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master. Speak with the Frostwolf Stable Master to earn credit for the capture.", progress = "Without your help, the Frostwolf Wolf Riders would not have mounts to ride into battle. You do us a great service!", completion = "I can only hope that those charged with collecting ram hides are as determined as you, {name}.\n\nAt this rate, we will have the stables full in a matter of hours!", sourceObjectiveStatus = "unverified-source-field" }
quests[7002] = { id = 7002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ram Hide Harnesses", progress = "While some of our soldiers are busy capturing wolves for the stable master, others must provide for the simple necessities that riding requires. I am speaking of riding harnesses, of course.\n\nYou must strike at the indigenous rams of the region. The very same rams that the Stormpike cavalry uses as mounts!\n\nSlay them and return to me with their hides. Once we have gathered enough hides, we will fashion harnesses for the riders. The Frostwolf Wolf Riders will ride once more!", completion = "Well done, soldier. I will notify you when I have stockpiled enough of the hides.\n\nCarry on!" }
quests[7003] = { id = 7003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zapped Giants", description = "I'm going to have to do something about the giants if I stay out here!  They're certainly not good for business, now are they?\n\nI've been working on a variant of a gnomish shrinking ray, but I'm using superior GOBLIN technological advances in its construction!  In an effort to avoid inconveniences for myself such as death, I'd like for you to try it out on any of the giants in Feralas.  You should find miniaturization residue on them after you shrink them - bring me back some!", sourceObjective = "Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form. Bring 15 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.", progress = "Miniaturization residue, I assure you, is a valuable commodity when it comes to engineering!  Well, it is valuable in that it helps me make sure the zapper won't do something as disappointing as explode on the user.\n\nOh, I mean for the zappers other than the one I gave you.  Absolutely!", completion = "Splendifimous!  Not only am I glad to see that you've returned with the residue, but also with all your major appendages intact!  That is, well, there was never any danger in using the Ultra-Shrinker, now was there!\n\nI do appreciate your effort on my behalf, {name}.  Truly, you are a friend to goblins everywhere.  Accept this as a token of my appreciation!", sourceObjectiveStatus = "unverified-source-field" }
quests[7021] = { id = 7021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Great-father Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Great-father Winter, who's currently in Orgrimmar!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", sourceObjective = "Speak with Great-father Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.", completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah.", sourceObjectiveStatus = "unverified-source-field" }
quests[7022] = { id = 7022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greatfather Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", sourceObjective = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge.", completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah.", sourceObjectiveStatus = "unverified-source-field" }
quests[7023] = { id = 7023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greatfather Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter, who's currently in Ironforge!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", sourceObjective = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge.", completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah.", sourceObjectiveStatus = "unverified-source-field" }
quests[7024] = { id = 7024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Great-father Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Great-father Winter, who's currently in Orgrimmar!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", sourceObjective = "Speak with Great-father Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.", completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah.", sourceObjectiveStatus = "unverified-source-field" }
quests[7025] = { id = 7025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treats for Greatfather Winter", description = "Hey, can you do Greatfather Winter a favor, um, little <boy/girl>?\n\nNot to needlessly talk about myself in the third person, but Greatfather Winter has been at this all day and he could use a treat himself.  Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot.  Think you could be a friend to the Greatfather and fetch some for me?", sourceObjective = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Ironforge.", progress = "All this talk of treats has given me a hankering for some myself.  Mmmm... gingerbread cookies and milk...", completion = "You're quite the helper to ol' Greatfather Winter there, {name}.  Have a great Feast of Winter Veil.\n\nHere's a little something... you know, for the effort.", sourceObjectiveStatus = "unverified-source-field" }
quests[7026] = { id = 7026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ram Riding Harnesses", progress = "The Stormpike Brigade cannot charge into battle bareback! We require harnesses for our mounts, after all, we are not savages.\n\nWhile we could easily slay the rams that roam near our base for the leather required to fashion a harness, doing so would be idiotic. We need those rams for mounts.\n\nYou must strike at our enemy's base, slaying the frostwolves they use as mounts and taking their hides. Return their hides to me so that harnesses may be made for the cavalry. Go!", completion = "Well done, soldier. I will notify you when I have stockpiled enough of the hides.\n\nCarry on!" }
quests[7027] = { id = 7027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empty Stables", description = "Just look at the stables, {name}! Empty! The Stormpike Brigade has no rams to ride - the cavalry is defunct.\n\nYou must help us, soldier. Take this training collar and enter the wilds of this valley. Locate the Alterac rams that roam throughout the area and use the collar to snare one. When you have captured a ram, return it to me and I shall place it in our stable.\n\nWhen we have enough rams, the ram rider commander will be notifed. With your help, the cavalry will be reborn!", sourceObjective = "Locate an Alterac Ram in Alterac Valley. Use the Stormpike Training Collar when you are near the Alterac Ram to 'tame' the beast. Once tamed, the Alterac Ram will follow you back to the Stable Master. Speak with the Stable Master to earn credit for the capture.", progress = "Without your help, the Stormpike Ram Riders would not have mounts to ride into battle. You do us a great service!", completion = "The stables will be full in no time at all. Keep up the good work!", sourceObjectiveStatus = "unverified-source-field" }
quests[7028] = { id = 7028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Evils", description = "The crystal caverns of Terramok lie to the west, deep within Maraudon... It is an ancient place with much history. And I am looking to get my hands on some of it, {class}. Relics of the old gods lie hidden behind the giant doors.\n\nIf you are willing to brave the twisted evils found in Maraudon, I believe I can make it worth your time. Collect the theradric crystal carvings you find, and return them to me.\n\nOnce I get the carvings, I will be able to... study them. These powers have been too long at rest...", sourceObjective = "Collect 15 Theradric Crystal Carvings for Willow in Desolace.", progress = "Don't ask questions!\n\nYou have my request.", completion = "Ha ha ha! I knew you'd be back.\n\n<Willow mutters.>\n\n...So easy to convince.\n\n...Will do anything for the right price. Heh heh heh...", sourceObjectiveStatus = "unverified-source-field" }
quests[7029] = { id = 7029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyletongue Corruption", description = "A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside.\n\nTake this vial, {name}. Fill it at the orange crystal pool found inside the caverns; the coating inside the vial will counter the toxins, turning it into a healing agent.\n\nFind the Vylestem vines inside the orange caverns, and use the purified liquid on them. The corruption will be purged from the plant, but do know that Vyletongue will still control it. He may use it against you...", sourceObjective = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\n\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\n\nHeal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village.", progress = "If you are able to heal the plant, it will again begin to grow. We must do what we can, {name}...", completion = "Thank you for returning this, {name}. With the remaining liquid you brought me, I can continue my studies.\n\nWhile there is still much to do, you have helped to heal some of the corruption that Vyletongue spread through Maraudon. Please take this with my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[7041] = { id = 7041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyletongue Corruption", description = "A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside.\n\nTake this vial, {name}. Fill it at the corrupted orange pool found inside the caverns; the coating inside the vial will counter the toxins, turning it into a healing agent.\n\nFind the Vylestem vines inside the orange caverns, and use the purified liquid on them. The corruption will be purged from the plant, but do know that Vyletongue will still control it. He may use it against you...", sourceObjective = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\n\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\n\nHeal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point.", progress = "If you are able to heal the plant, it will again begin to grow. We must do what we can, {name}...", completion = "Thank you for returning this, {name}. With the remaining liquid you brought me, I can continue my studies.\n\nWhile there is still much to do, you have helped to heal some of the corruption that Vyletongue spread through Maraudon. Please take this with my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[7042] = { id = 7042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Winter Veil Treats", description = "Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.\n\nWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains area of Hillsbrad Foothills, and that's where our man went.\n\nSee if both are out there, safe and sound!", sourceObjective = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Hillsbrad Foothills.", completion = "Y-y-you can h-h-hear me!  Thank the b-b-bottom line!\n\nI'm not really a s-s-snowman - my n-n-name is Sacks, and I w-w-work for the Ironforge b-b-branch of Smokywood Pastures... I g-g-got sent out here to look for a m-m-missing package, when I was attacked by a c-c-creature I have never seen b-b-before!\n\nSo v-v-very cold...", sourceObjectiveStatus = "unverified-source-field" }
quests[7043] = { id = 7043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're a Mean One...", description = "A creature called \"The Abominable Greench\" stole our shipment of treats, {name}.  Be careful though!  He's vicious and a bunch of those little green gnomes do his bidding!\n\nYou're gonna need some help in facing him.  Rumor has it he's holding our treats and our beloved Metzen the Reindeer at Growless Cave in the Hillsbrad Foothills!  Find the treats {name} and bring them back before the celebration is ruined and all the children of Stormwind are disappointed!", sourceObjective = "Recover the Stolen Treats and free Metzen the Reindeer after defeating the Abominable Greench, who is hiding out near Growless Cave in the Hillsbrad Foothills.", progress = "{name} - our Feast of Winter Veil will be ruined without those treats to restock!  Graccu himself will miss out on sharing his delicious meat pies with all the good boys and girls this season...", completion = "You found it!  You've saved Smokywood Pasture's Feast of Winter Veil!\n\nPoor Sacks... we'll be sure to send a team out there and figure out a way to unfreeze him.  Hopefully, he'll be back in time for the day of the Feast; he'll need to make up missed time working though.  Still, this wouldn't even be possible if it weren't for you!", sourceObjectiveStatus = "unverified-source-field" }
quests[7044] = { id = 7044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legends of Maraudon", description = "A dark satyr called Lord Vyletongue spread his evil through these twisting caves, poisoning the minds of all inside. He still resides beyond the purple crystals.\n\nVyletongue also created a living symbol of his corruption called Noxxion that dwells beyond the orange crystals. Together, they have stolen the two parts of my brother's scepter. Celebras, my brother... he wanders blindly inside, cursed by corruption.\n\nYou must help him! Find the pieces, and speak to my brother... somehow.", sourceObjective = "Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.\n\nFind a way to speak with Celebras.", progress = "I have awoken from a nightmare that seemed it would never end...", completion = "Now that you have recovered the two parts of my scepter, I have hope that Maraudon may one day be rid of the Vyle corruption.", sourceObjectiveStatus = "unverified-source-field" }
quests[7045] = { id = 7045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Smokywood Pastures' Thank You!", description = "We at Smokywood Pastures appreciate the recovery of the stolen treats, {name}.  For that, we'd like to offer you a special gift... presented by none other than Greatfather Winter himself!\n\nPlease, speak with Greatfather Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!", sourceObjective = "Speak with Greatfather Winter in Ironforge.", completion = "Ho ho hello, adventurer!\n\nThe goblins told me that you have earned a special gift this holiday season, and I am pleased to give it to you.  Here you go - have a wondrous Feast of Winter Veil this and every season in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[7046] = { id = 7046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scepter of Celebras", description = "My scepter was once a source of hope for me. It once granted me power over these caverns. I had hoped to bring peace to the spirit of my uncle...\n\nFor the two parts to once again become one, I will need your assistance in performing the ritual. Please follow me, and listen to my instructions while I channel the energy required to reunite the rod with the diamond.\n\nTogether, we shall create the Scepter of Celebras once again!", sourceObjective = "Assist Celebras the Redeemed while he creates the Scepter of Celebras.\n\nSpeak with him when the ritual is complete.", progress = "If you wish to restart the ritual, please abandon our first attempt and then speak to me again.", completion = "Please take this, and know that the power allotted to you now must be used for good. Continue your journey through the caverns, and with hope, you will find the remains of my uncle. Much danger awaits you, {name}.\n\nSpeak with me again should the need arise.", sourceObjectiveStatus = "unverified-source-field" }
quests[7061] = { id = 7061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Feast of Winter Veil", description = "Here - if you are interested in learning more about the Feast of Winter Veil, read this book.  While I think our recognition of the legend is the appropriate one, I'm enough of a student of legends to appreciate the collection of all information into a single source.\n\nWhen you're done, take the book to Baine Bloodhoof in Thunder Bluff.  I know for a fact he'd be interested in hearing that others have taken an interest in the lore of our people.", sourceObjective = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday. When you are finished with the book, deliver it to Baine Bloodhoof in Thunder Bluff.", progress = "I bid you welcome to Mulgore and our humble community of Thunder Bluff, friend.  I always take an interest in those who choose to take an interest in the kingdom, its people, and its lore.  Is this why you are standing before me?", completion = "The legends and lore surrounding the Winter Veil are ones that have faded from the forefront of public though over the years.  Yes, I know that the goblins are helping to revive the season for their own ends, the fact that our people reflect upon it at least in some form does good to keep such lore alive.\n\nYour desire to go beyond the material and learn about our past is an admirable trait, young {class}.  I salute your wisdom.", sourceObjectiveStatus = "unverified-source-field" }
quests[7062] = { id = 7062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reason for the Season", description = "Gifts, treats, presents... bah, I say!\n\nThose goblins pollute the true meaning of this season - the Feast of Winter Veil.  This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit!\n\nIf you're interested in learning what the Feast is all about for yourself, ask Historian Karnik at the Explorers' League.  I'm sure he'll be surprised that someone cares about history rather than getting presents.", sourceObjective = "Speak with Historian Karnik at the Explorers' League in Ironforge about the Feast of Winter Veil.", completion = "The Feast of Winter Veil, you say?  Alas, in times past it held a more substantial meaning to us dwarves.  Nowadays, it seems as though others have turned the legend of Greatfather Winter into something that helps to sell candies and presents.\n\nIt's no surprise that Goli is bitter about that sort of change.  He and other dwarves like him cling to our past like a banner of war.  While I think a little celebration is always good, it is important to remember the origins of the Feast.", sourceObjectiveStatus = "unverified-source-field" }
quests[7063] = { id = 7063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Feast of Winter Veil", description = "Here - if you are interested in learning more about the Feast of Winter Veil, read this book.  While I think our recognition of the legend is the appropriate one, I'm enough of a scholar to appreciate the collection of all information into a single source.\n\nWhen you're done, take the book to Muradin Bronzebeard.  I know for a fact he'd be interested in hearing that others have taken an interest in the older legends.", sourceObjective = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday. When you are finished with the book, deliver it to Muradin Bronzebeard in Ironforge.", progress = "I bid you welcome to the Kingdom of Ironforge, friend.  I always take an interest in those who choose to take an interest in the kingdom, its people, and its lore.  Is this why you are standing before me?", completion = "The legends and lore surrounding the Winter Veil are ones that have faded from the forefront of public thought over the years.  While I recognize that the goblins are helping to revive the season for their own ends, the fact that the citizenry thinks about it at least in some form does good to keep such lore alive.\n\nYour desire to go beyond the material and learn about our past is an admirable trait, young {class}.  I salute your erudite nature.", sourceObjectiveStatus = "unverified-source-field" }
quests[7064] = { id = 7064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption of Earth and Seed", description = "Deep in Maraudon lives an evil creature of chaos--Princess Theradras is an elemental force of earth related to the Old Gods. Ages ago, she and Zaetar, first son of Cenarius, began a relationship. The offspring of their time together became known to the people of Kalimdor as centaur. Ever-thankful creatures, the centaur killed Zaetar, and now hold Zaetar's remains. My quest here is to find those powerful enough to slay Theradras so we may recover Zaetar's remains before returning to Stonetalon.", sourceObjective = "Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace.", completion = "This is most wonderful news, {name}! Thank you!\n\nI will speak with Marandis and ask his wisdom on the topic of Zaetar's remains, but at least you have overcome the hardest of the tasks.\n\nI was told that if we were successful in our mission, I had permission to reward those who aided us. I was given these items as tokens from our people--you may choose one.", sourceObjectiveStatus = "unverified-source-field" }
quests[7065] = { id = 7065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption of Earth and Seed", description = "In the depths of Maraudon lives a creature of chaos and evil, {name}. Princess Theradras is an elemental force of earth related somehow to the Old Gods. Ages ago, she was sought out by Zaetar, first son of Cenarius. The offspring of their... relationship are the creatures known as centaur. Ever-thankful creatures, the centaur killed Zaetar, and now Theradras keeps his remains. My quest here is to find those powerful enough to slay Theradras so we may recover Zaetar's remains before returning to Stonetalon.", sourceObjective = "Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace.", completion = "This is most wonderful news, {name}! Thank you!\n\nAlthough it concerns me that you were not able to bring back Zaetar's remains, who am I to question the will of Cenarius' first born. Perhaps now the will of the centaur will break and their thirst for blood will lesson--we can only hope.\n\nIf successful in our mission, I was given these items to reward any who aided us. You may choose one as a token of thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[7066] = { id = 7066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seed of Life", description = "The misbegotten centaur--my sons and daughters--have need of their father.\n\nLook around you--this place rings of hope and all that my father Cenarius preaches. It sprung from me! And I cannot take that away from them... not even for their crimes against me.\n\nBut there is one thing I would ask of you to ease my brother's mind. Take this... it is the first seed that fell from the life my remains nourished. Tell him my spirit remains here, and that I live on. I am sure he will understand.", sourceObjective = "Seek out Remulos in Moonglade and give him the Seed of Life.", progress = "You have the scent of corruption on you, {name}... much like many adventurers these days. But something about you is different. Is there something you've come to speak to me about? You have an aura about you that seems familiar, but I cannot place it.\n\nPlease, I implore you, tell me why you've sought an audience with me.", completion = "So my brother has finally found peace? I am proud to have lived to see this day. In all his arrogance and anger, I truly thought he was lost to us, but this... this symbol of his sacrifice only proves that he is not lost--he has only been reborn. He takes his place in nature as was his duty.\n\nThank you, {name}. By bringing this to me, you have secured a small amount of hope that I thought I had once lost. This seed will be important to the people of this war-torn land some day... I can sense it.", sourceObjectiveStatus = "unverified-source-field" }
quests[7067] = { id = 7067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pariah's Instructions", description = "Though exiled as a heretic, my beliefs still ring true--that alone drives me onward. But for my destiny to be complete, I need the aid of an outsider... one not of any centaur tribe.\n\nThe task requires someone to enter the holy halls of Maraudon--a tomb my people protect, and only the most devout are ever allowed to enter.\n\nIf you agree to aid me, then you need only nod. I will pass you a parchment with my instructions on it. Read it over and consider my words.", sourceObjective = "Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace.", progress = "What did you decide, {name}? Can you help me? Will you set foot on holy ground to help me forge one great centaur tribe!?", completion = "This is it, {race}! This is it! Now I can begin the great task of uniting the tribes. Thank you.\n\nTake this for your efforts, please. I hope when next we meet, it will be on much different terms.", sourceObjectiveStatus = "unverified-source-field" }
quests[7068] = { id = 7068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowshard Fragments", description = "Strong magics be found in the centaur holy place... the holy place of Maraudon. The Desolace tribes of centaur protect that place wit' their lives, but they canna stop us from takin' what we need.\n\nYou, you head to this Maraudon place and find the rock creatures made of shadowshard. You bring me the purple crystals, and Uthel'nay make you somethin' for your time.\n\nThe place be dangerous, so maybe you be bringing some friends.", sourceObjective = "Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar.", progress = "You find the crystals yet? Rituals of power, spells of great strength--those shadowshards maybe very helpful in all kind of arcane magics.", completion = "Ah, these be perfect for me magics. Here, you take one of these trinkets and be on your way... me got much studyin' to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[7070] = { id = 7070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowshard Fragments", description = "I've recently begun testing various crystals and their arcane properties. Lady Proudmoore has given me leave to ask travelers heading into Desolace to seek out a place called Maraudon. Within the ruined temple are great elementals composed of purplish stones I've named shadowshards.\n\nIf you decide to head that direction and find some of the crystals, I would be very thankful. I could even fashion you a trinket from them if you so desired.", sourceObjective = "Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh.", progress = "Have you made the trip yet? I realize it'd be quite dangerous, but if you were successful, it would very much be worth it.", completion = "These are perfect, {name}. I actually had other adventurers return from there also and from them I was able to fashion these... please, feel free to take one for your hard work. And thank you again for more samples to study.", sourceObjectiveStatus = "unverified-source-field" }
quests[7081] = { id = 7081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alterac Valley Graveyards", description = "The graveyards in Alterac Valley are prized territories.  Both the Horde and the Alliance fight savagely for these sacred grounds.  Are you, {name}, ready to join that fight?\n\nI want you to assault an enemy graveyard.  Find a graveyard with a Horde banner in its midst, and pull it from the ground!  Do that, and your task will be complete....\n\nBut if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.", sourceObjective = "Assault a graveyard, then return to Sergeant Durgen Stormpike in the Alterac Mountains.", progress = "{name}, you have not yet assaulted a graveyard.  Return to me when this task is complete!", completion = "Well done!  Graveyards are vital to our control of Alterac Valley.  When you capture one, you help ensure the Alliance's sovereignty here.\n\nGo now, {name}.  Reenter the battle, and if you see a graveyard under the Horde's control... you know what to do!", sourceObjectiveStatus = "unverified-source-field" }
quests[7082] = { id = 7082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Graveyards of Alterac", description = "The battle lines of Alterac Valley are ever shifting.  Territories swing back and forth as we meet our opponents in deadly combat.  And graveyards, {name}, are where battles rage most fierce.\n\nI want you to attack an Alliance held graveyard!  Find a graveyard with an Alliance banner in its midst and pull it from the ground.\n\nDo that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.", sourceObjective = "Assault a graveyard, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.", progress = "Attack a graveyard held by the Alliance!", completion = "Well done, {name}!  With each graveyard under our control, the spirits of our enemies will wander more lost and aimless.", sourceObjectiveStatus = "unverified-source-field" }
quests[7101] = { id = 7101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Towers and Bunkers", description = "Towers and bunkers are important positions, and we must capture and hold them all!  So to that end, I want you to attack a bunker that is controlled by the enemy.\n\nTo do that, enter one with an Alliance banner.  You will see another banner inside.  Pull out that banner, and a white Horde banner will appear in its place.  Well done!\n\nAt that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!", sourceObjective = "Capture an enemy tower, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.", progress = "You haven't yet assaulted a bunker, {name}!  Are you waiting for others to claim your glory?", completion = "I heard of your mission's success!  That pleases me...\n\nOur troops can now charge forward with impunity, and show the Alliance that Alterac Valley is no place for them!", sourceObjectiveStatus = "unverified-source-field" }
quests[7102] = { id = 7102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Towers and Bunkers", description = "Towers and bunkers are key defensive positions, and so we must hold as many as possible!  I want you to attack a tower or a bunker in Alterac Valley.\n\nTo do that, enter a tower with a Horde banner atop it.  You will see another enemy banner inside.  Pull out that banner, and a white Alliance banner will appear in its place.  Well done!\n\nAt that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!", sourceObjective = "Destroy the banner at an enemy tower or bunker, then return to Sergeant Durgen Stormpike in the Alterac Mountains.", progress = "You haven't yet assaulted a tower, {name}!  What are you waiting for?", completion = "I received a field report stating you helped secure an enemy banner.  Well done, {name}!  With their ranged troops out of position we can move the line of battle forward!", sourceObjectiveStatus = "unverified-source-field" }
quests[7121] = { id = 7121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quartermaster", description = "{name}, our quartermaster charged me to direct new recruits to him.  He needs supplies from caches stored in the mines of Alterac, and he'll probably send you to get them.\n\nFollow the road.  You'll find our quartermaster to the west.", sourceObjective = "Speak with the Stormpike Quartermaster.", completion = "It's good to see fresh troops here, {name}, but with a little luck you'll get into some action and won't be fresh for long!\n\nSpeak with me again.  I have tasks I must discuss with you....", sourceObjectiveStatus = "unverified-source-field" }
quests[7122] = { id = 7122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture a Mine", description = "The mines in Alterac Valley hold more than just minerals.  Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them!\n\nCapture a mine, then return to me.  To capture a mine, enter one that we do not control and kill its leader.  When you do that, the mine will be ours, and we'll send troops to protect it!", sourceObjective = "Capture a mine that the Stormpike does not control, then return to Sergeant Durgen Stormpike in the Alterac Mountains.", progress = "You haven't captured the mine yet, {name}!\n\nAfter we control a mine, it will be much easier to gather minerals and supplies from it.", completion = "You did it!  Well done, {name}!\n\nWhen we control a mine and have troops stationed there, it's much easier to gather minerals and supplies from it.", sourceObjectiveStatus = "unverified-source-field" }
quests[7123] = { id = 7123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with our Quartermaster", description = "{name}, the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley.  Speak with him; he will tell you more.\n\nFollow the road west into the bunker, then take the west exit and you'll find our quartermaster.", sourceObjective = "Speak with the Frostwolf Quartermaster.", completion = "Hail, {name}!  It is good to see a {class} like yourself, eager to do his part for the Horde.  Speak with me again, for I have vital tasks for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[7124] = { id = 7124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture a Mine", description = "As battle rages over the landscape of Alterac Valley, so too does it rage through the Coldtooth and Irondeep mines.  Both are rich sources of minerals and both are used to store supplies; it's no wonder they are so highly valued!\n\nHelp our war effort, {name}!  Capture one of the mines for the Horde!  To capture a mine, enter one that we do not control and kill its leader.  When that is done, the mine will be ours and we'll send troops to protect it!", sourceObjective = "Capture a mine, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.", progress = "You haven't yet captured a mine, {name}!  Find one that we do not control and defeat it's leader!", completion = "You captured a mine!  With our own warriors protecting it, it will be much simpler to extract minerals from its depths, or gather supplies that have been cached there.\n\nWell done, {name}.  The deed you have done is a great boon to our battle efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[7141] = { id = 7141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Alterac", description = "The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore.  We can't allow the Horde to stop our scholarly pursuits!  Defeat the Frostwolf general, Drek'Thar.  With him dead, the orcs will lose their edge.\n\nDrek'Thar is in Frostwolf Keep, in the south of Alterac Valley.  Vanquish him, and then return to me.", sourceObjective = "Enter Alterac Valley, defeat the Horde general Drek'thar, and then return to Prospector Stonehewer in the Alterac Mountains.", progress = "Go, {name}.  Go to Alterac Valley and defeat the orc general!", completion = "Well done, {name}!  With the Horde's nose bloodied after the death of their general, we'll have the breathing room we need to explore!", sourceObjectiveStatus = "unverified-source-field" }
quests[7142] = { id = 7142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Alterac", description = "The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out!  To win the battle for Alterac, we must defeat their general, Vanndar Stormpike!\n\nYou will find Vanndar in Dun Baldar, in the north of Alterac Valley.\n\nDestroy him, {name}, and then return to me.", sourceObjective = "Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike. Then, return to Voggah Deathgrip in the Alterac Mountains.", progress = "We will not suffer the dwarves in our home!  Fall upon our foes and defeat their leader, general Stormpike!", completion = "Well done, {name}!  Stormpikes have no hope in this foolish invasion.\n\nHah!  So far, all they've done is get their general killed!", sourceObjectiveStatus = "unverified-source-field" }
quests[7161] = { id = 7161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Grounds", description = "Hail, {class}. It has been a long time since we have had the chance to answer the call of battle. The old feelings are slow to rise but once awakened, the blood does rush. The battle rage returns...\n\nAll newcomers to the Valley must first complete the rite of battle.\n\nDeep within the Wildpaw gnoll cave is a banner of the Frostwolf. Venture forth and recover the banner. Return it to me and I shall grant you the Frostwolf initiate's insignia.", sourceObjective = "Travel to the Wildpaw cavern located southeast of the main base in Alterac Valley and find the Frostwolf Banner. Return the Frostwolf Banner to Warmaster Laggrond.", progress = "Wake up! Wake up, {name}! This is not a dream. You really are entrenched in the midst of a raging battle!", completion = "That burning sensation you feel is your soul being awakened. Your spirit has accepted the call to arms.\n\nYou are now one of the Frostwolf, {name}. Congratulations.\n\nCarry this insignia with you at all times. As you advance among the ranks of Frostwolf, I will replace the insignia with other, more powerful insignias.\n\nPerhaps someday you will be exalted among the Frostwolf Clan. Should that day ever come, you will be granted the Eye of Command.", sourceObjectiveStatus = "unverified-source-field" }
quests[7162] = { id = 7162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Grounds", description = "You've arrived just in time, {class}. These Frostwolf savages just won't give up! We must show them the might of the Stormpike. They must bow to our superiority.\n\nBefore you make your way to the field of battle, you will want to join the rank of Stormpike.\n\nSouthwest of Dun Baldar, you will find the Icewing Caverns. Planted deep within the caverns is a Stormpike Banner. Venture forth and recover that banner. Return it to me, and you will have earned a Stormpike initiate's insignia.", sourceObjective = "Travel to the Icewing Caverns located southwest of Dun Baldar in Alterac Valley and recover the Stormpike Banner. Return the Stormpike Banner to Lieutenant Haggerdin in the Alterac Mountains.", progress = "Beware the harpies of the region, {class}. They'll not think twice to rip out your throat!", completion = "Take and wear this insignia with pride, {name}. As your rank among the Stormpike grows, so too will the insignia. Return to me as you gain honor with Stormpike, and I shall replace your insignia with other, more powerful insignias.\n\nPerhaps someday you will grow to be a legend on this field of battle. Should that day ever come, you will be granted the Eye of Command.", sourceObjectiveStatus = "unverified-source-field" }
quests[7163] = { id = 7163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise and Be Recognized", progress = "<Warmaster Laggrond salutes you.>\n\nIt is your time, {name}. You have done much for the Frostwolf Clan and in doing so, earned a place as not only a soldier of Frostwolf but also as a friend.\n\nWell done! Present your initiate's insignia.", completion = "This new insignia reflects your rank amongst the Frostwolf. Keep it on you at all times.\n\nAnd {class}... Die with honor!" }
quests[7164] = { id = 7164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honored Amongst the Clan", progress = "It is good to see you again, {class}. I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.\n\nYour time has come again, {name}. You have earned a new ranking and as such, a new insignia denoting this rise in stature.\n\nPresent your insignia.", completion = "<Warmaster Laggrond salutes.>\n\nGo, {name}! Continue your defense of the Frostwolf. This war must be won! For Drek'Thar! For the Warchief!" }
quests[7165] = { id = 7165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earned Reverence", progress = "So many slain. Blood drenches the fields. Yet... You live... You have persevered. You have led our armies to many victories. For this, then, soldier, you have earned a new rank.\n\nPresent your insignia.", completion = "<Warmaster Laggrond roars.>\n\nThey have already begun telling tales of your deeds, soldier. The Stormpike shakes in fear when your name is uttered. Carry on!" }
quests[7166] = { id = 7166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendary Heroes", progress = "Your radiate command and power, {class}. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name.\n\nRise, Hero of Frostwolf. Rise and be honored!\n\nPresent your insignia.", completion = "Soon, all on the field of battle will be under your watchful eye. Command of the Valley and its troops will be yours!" }
quests[7167] = { id = 7167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Command", progress = "Drek'Thar sings your praises. Kalimdor is abuzz with tales of your heroics. The Warchief glows - your stalwart defense of our clan has pleased him greatly.\n\nYou have earned the Eye of Command.\n\nPresent your insignia, Commander {name}.", completion = "Channel the power of the insignia. Let the enemy hear your words. The might of the Horde is unquestionable!" }
quests[7168] = { id = 7168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise and Be Recognized", progress = "Most do not live long enough to rise above their own mediocrity. You have proven yourself to be an exemplary soldier, {class}. The time has come.\n\nPresent your insignia.", completion = "Let our enemies see that a soldier of rank has struck them down! Fight for the glory of Stormpike!" }
quests[7169] = { id = 7169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honored Amongst the Guard", progress = "The base buzzes with news of your exploits in the Field of Strife! You have struck mighty blows against our enemy - crushing their morale! For this, you have earned a rank of honor among the Stormpike.\n\nPresent your insignia.", completion = "The king has been made aware of your battlefront heroics, {class}. Continue in your stalwart defense of the Stormpike Guard!" }
quests[7170] = { id = 7170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earned Reverence", progress = "I must know, {name}. When you look directly into the eyes of the enemy, do you see fear? Do they now cower in your presence? They must realize that they are defeated!\n\nYou have earned reverence among the Guard. Present your insignia!", completion = "When we first met, I would have never guessed that a hero was in the making. Carry on, soldier!" }
quests[7171] = { id = 7171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendary Heroes", progress = "Before me stands an exalted hero of the Alliance.\n\n<Lieutenant Haggerdin salutes.>\n\nFew have earned such a rank among the Stormpike. I have watched the enemy fall before you. I have seen their resolve crumble in your presence. When you enter the fray, you become the beacon of hope for our forces!\n\nPresent your insignia.", completion = "Surely it will be you who carries the Eye of Command!" }
quests[7172] = { id = 7172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Command", progress = "Let them hear your voice, Commander {name}! Let them know fear. Show them what power the Stormpike holds in their rank!\n\nPresent your insignia.", completion = "It is you who must lead our troops to victory, Commander! The soldiers are under your command. They will follow your direct orders. Lead them.... Crush the Frostwolf." }
quests[7181] = { id = 7181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Korrak", description = "The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power.\n\nThey are lead by Korrak the Bloodrager - a cruel and cunning beast.\n\nA strike against Korrak could prove to be a crushing blow to the Winterax clan. Slay the beast and be rewarded!You will be able to choose one of these rewards:", sourceObjective = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\n\nShould Korrak make himself known, destroy him and return to Warmaster Laggrond.", sourceObjectiveStatus = "unverified-source-field" }
quests[7201] = { id = 7201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Element", description = "There is work to be had for those venturing into the depths, {name}.\n\nThe Dark Irons have mastered creation of extremely powerful golems.\n\nInitial reports from our spies indicate that the dwarves use a unique power source to give their creations incomparable killing power.\n\nJust imagine what we could do with our abominations if we could get our hands on this essence of the elements! Turn that city upside down if you must, but do not return until you have found the essence! Payment will be worth the risk.", sourceObjective = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.", progress = "<Rubs her hands together.>\n\nShow them to me!", completion = "Wonderful! I will have these sent by courier to the Undercity at once!\n\nAs for you - here is payment, as promised. Keep the change, you filthy beast!", sourceObjectiveStatus = "unverified-source-field" }
quests[7202] = { id = 7202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrak the Bloodrager", description = "The indigenous Winterax trolls of the region are ruthless savages that would love nothing more than to have our bones added to their foul stew.\n\nWe must show them our might!\n\nWe have recovered tomes from their caves that detail their leadership hierarchy. The artifacts indicate that their leader, Korrak the Bloodrager, tends to remain hidden until given a reason to make his presence known.\n\nDeath to Korrak would mean death to Winterax Clan! Slay him and return.You will be able to choose one of these rewards:", sourceObjective = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\n\nShould Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Alterac Mountains.", sourceObjectiveStatus = "unverified-source-field" }
quests[7221] = { id = 7221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Prospector Stonehewer", description = "Ah, {name}, reporting for duty are you?  Great, the Stormpikes can use everyone we can muster!\n\nSpeak with Prospector Stonehewer in Dun Baldar.  She's recruiting for a vital mission into enemy territory.  You'll find Stonehewer in the bottom of the Dun Baldar garrison.\n\nAnd keep an eye out as you go through Dun Baldar.  There's plenty to do for a hardworking {class} who's not afraid to get <his/her> hands dirty.", sourceObjective = "Speak with Prospector Stonehewer in the Dun Baldar garrison.Ah, {name}, reporting for duty are you?  Great, the Stormpikes can use everyone we can muster!\n\nSpeak with Prospector Stonehewer in Dun Baldar. She's recruiting for a vital mission into enemy territory. You'll find Stonehewer in the bottom of the Dun Baldar garrison.\n\nAnd keep an eye out as you go through Dun Baldar. There's plenty to do for a hardworking {class} who's not afraid to get <his/her> hands dirty.", sourceObjectiveStatus = "unverified-source-field" }
quests[7222] = { id = 7222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Voggah Deathgrip", description = "A {class}?  Good!  We are glad to see you in Alterac, {name}.  Interloping dwarves and their allies invade our valley, and we welcome all in the Horde to join us in righteous slaughter!\n\nSpeak with Voggah Deathgrip.  He is looking for agents for an important mission into the Alliance's stronghold in Alterac Valley!\n\nYou will find Voggah in Frostwolf Keep.", sourceObjective = "Speak with Voggah in Frostwolf Keep.A {class}?  Good!  We are glad to see you in Alterac, {name}. Interloping dwarves and their allies invade our valley, and we welcome all in the Horde to join us in righteous slaughter!\n\nSpeak with Voggah Deathgrip. He is looking for agents for an important mission into the Alliance's stronghold in Alterac Valley!\n\nYou will find Voggah in Frostwolf Keep.", sourceObjectiveStatus = "unverified-source-field" }
quests[7223] = { id = 7223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor Scraps", description = "Battles rage constantly in Alterac Valley, and the supplies we get from Ironforge are not enough to outfit our experienced troops.\n\nIf you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!", sourceObjective = "Bring 20 Armor Scraps to Murgot Deepforge in Dun Baldar.", progress = "Did you bring any armor scraps, {name}?", completion = "These are some good pieces, {name}.  I can use them to fashion new equipment for our troops.\n\nIf my supply level gets high enough, then maybe our seasoned fighting units will enter the field!", sourceObjectiveStatus = "unverified-source-field" }
quests[7224] = { id = 7224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemy Booty", description = "When you fight the enemy, gather the scraps of their armor and bring them to me.  I'll use those scraps to make armor for our own troops!", sourceObjective = "Bring 20 Armor Scraps to Smith Regzar in Frostwolf Village.", progress = "How goes the hunting, {name}.  Do you have any armor scraps for me?", completion = "These will do nicely.  I'll melt them down and patch them up and you'll never know they came from those Stormpike cowards!\n\nThanks, {name}.  And let me polish up that armor of yours...", sourceObjectiveStatus = "unverified-source-field" }
quests[7241] = { id = 7241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of Frostwolf", description = "The drums of war sound off in a distant land, {class}. The favored clan of your Warchief is under attack from the nefarious Stormpike Guard of Ironforge.\n\nBy the looks of you, I can discern that you are indeed battle hardy and prepared to take on the cause of the Frostwolf.\n\nIt is you who must now take the next step in your evolution.\n\nNorth of Tarren Mill, in Alterac,  you will find the entrance to Alterac Valley. It is there that you will find Warmaster Laggrond. Hurry {class}, for the battle is upon us!", sourceObjective = "Venture to Alterac Valley, located in the Alterac Mountains. Find and speak with Warmaster Laggrond - who stands outside the tunnel entrance - to begin your career as a soldier of Frostwolf. You will find Alterac Valley north of Tarren Mill at the base of the Alterac Mountains.", completion = "To become a soldier of Frostwolf, one must first be tested...", sourceObjectiveStatus = "unverified-source-field" }
quests[7261] = { id = 7261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sovereign Imperative", description = "We are fighting a brutal battle in the valleys of Alterac. The savage Frostwolf Clan challenges the might of the Stormpike! They must be exterminated in the name of King Magni Bronzebeard! The taking, culling, and turning of that land is a sovereign and territorial imperative to the kingdom of Ironforge.\n\nAlas, soldiers do not grow on trees! Report to Lieutenant Haggerdin outside Alterac Valley to begin your tour of duty and honor amongst the Stormpike.", sourceObjective = "Travel to Alterac Valley in the Hillsbrad Foothills. Outside of the entrance tunnel, find and speak with Lieutenant Haggerdin.\n\nFor the glory of Bronzebeard!", completion = "Let's get to work!", sourceObjectiveStatus = "unverified-source-field" }
quests[7281] = { id = 7281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brotherly Love", description = "Tragic... My brother faces me on the field of battle: A commander for the Stormpike.\n\nOf the four Stormpike Commanders, he is undoubtedly the most dangerous. Perhaps if he is slain, the Banshee Queen could turn him as she did me - show him the error of his ways...\n\nDeep within enemy territory you will find my brother. Slay him and return to me. I trust that you are capable of completing this mission, soldier.\n\nAnd soldier, do not go alone.", sourceObjective = "Travel into Stormpike territory and slay Commander Karl Philips. Return to Commander Louis Philips when the task is complete.", completion = "Your heroics will not go unnoticed, {name}.\n\nI must waste no time if he is to be saved. Sylvanas must be contacted!", sourceObjectiveStatus = "unverified-source-field" }
quests[7282] = { id = 7282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brotherly Love", description = "He must be put out of his misery, soldier! He knows not what he does. He has become a mindless servant of the dreaded Banshee Queen.\n\nVenture forth, across the Field of Strife, to the depths of Frostwolf territory. Find my brother and destroy him. His torment must come to an end.", sourceObjective = "Travel into Frostwolf territory and slay Commander Louis Philips. Return to Commander Karl Philips when the task is complete.", completion = "You did remember to burn the corpse, didn't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[7301] = { id = 7301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen Sky Lords", description = "We got them held prisoner, {race}. I'm talking about their Wing Commanders. It was a furious battle in the skies but they finally fell! Unfortunately, our best pilots were shot down in a counterattack against Frostwolf Keep. You gotta find out what happened to them.\n\nSearch Tower Point West and Frostwolf Keep. These were their last known locations. Search these areas thoroughly.", sourceObjective = "Travel to Frostwolf territory and search for Wing Commander Slidore, Wing Commander Vipore, and Wing Commander Ichman. Return to Commander Duffy should you complete your mission.", completion = "Unbelievable! You did free them, right? Right??? Well at the very least we know where they were held.", sourceObjectiveStatus = "unverified-source-field" }
quests[7302] = { id = 7302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen Sky Lords", description = "Our air support is in shambles, {name}. The Wing Commanders were shot down over enemy territory. You must find out what became of them so that we can attempt a rescue!\n\nGuse was last seen flying over the Icewing Bunker. Jeztor's War Rider was spotted near the Stormpike lumber mill. Mulverick... that reckless fool was seen crashing near the Dun'Baldar North Bunker.\n\nThat's all the information I have. Move out! Search through the areas thoroughly.", sourceObjective = "Find out what became of Wing Commander Guse, Wing Commander Jeztor, and Wing Commander Mulverick. Return to Commander Mulfort should you complete your mission.", completion = "Well done! The information you recovered will be invaluable to our cause.", sourceObjectiveStatus = "unverified-source-field" }
quests[7321] = { id = 7321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soothing Turtle Bisque", description = "Who says that the undead don't know anything about cooking? Take my secret recipe for Turtle Bisque, for example. I've known folks that would come back from the dead just to enjoy a bowl! Heh, heh...\n\nSpeaking of which, I haven't been able to make any lately.  I used to head over to Lake Lordamere myself to hunt snapjaws, the nasty things, but I can't pull myself away from my work here.\n\nIf you bring me some Turtle Meat from the snapjaws, I'll show you how it's done!", sourceObjective = "Bring 10 pieces of Turtle Meat to Christoph Jeffcoat in Tarren Mill.", progress = "Any luck finding the ingredients?  I'll tell you, the alliance maggots are far too numerous in this area now... In my opinion, they have come far too close already...", completion = "My soothing turtle bisque will keep you warm on a cold night... if you care about that kind of thing.", sourceObjectiveStatus = "unverified-source-field" }
quests[7341] = { id = 7341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fair Trade", progress = "Greetings, {race}. I am Kolark, Bounty {class} from Thunderbluff. Much of the world I have traveled and much I have seen.\n\nMy journeys across the South Seas led to the discovery of these wonderous thorium headed arrows. Alas, I have an endless supply of the arrows but have exhausted my supply of shells. Bah, no self respecting Tauren would ever be caught dead using a flimsy bow. The arrows are useless!\n\nI will offer a trade: An even exchange of thorium shells for my thorium headed arrows. Deal?", completion = "Excellent! I am a Tauren of my word, {race}. The arrows are yours." }
quests[7342] = { id = 7342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arrows Are For Sissies", progress = "Can you believe this rubbish?! The last shipment of ammunition from Kharanos was botched! All we have for ammo now are these flimsy, good for nothing arrows! What in the world am I going to do with 500,000 thorium headed arrows?\n\nI'll tell you what, kid. If you can bring me thorium shells, I'll trade you thorium headed arrows - straight up! Deal?", completion = "A done deal if I ever saw one! The arrows are yours." }
quests[7367] = { id = 7367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defusing the Threat", description = "The Frostwolf have their front lines and bases booby trapped, {class}. You have to watch your step when invading enemy territory.\n\nIf you want to make a solid strike against them, you must destroy their source of anti personnel munitions - I'm talking about their explosives expert. If you kill him, you are safe to disarm the mines. As long as he is kept down, the mines will also stay down.\n\nYou will probably find him in a tower near the Iceblood Garrison. Good luck!", sourceObjective = "Find the Frostwolf Explosives Expert and kill him. Return to the Stormpike Explosives Expert when the task is complete.", sourceObjectiveStatus = "unverified-source-field" }
quests[7368] = { id = 7368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defusing the Threat", description = "I know all about landmines. I'm the one that lays all the mines on the front lines here, after all.\n\nIf you want to defuse the Stormpike mine fields, all you have to do is kill their explosives expert. That dwarven coward is no doubt hiding in the first tower on the Field of Strife. Take him out and those landmines won't come back after they've been disarmed.\n\nIf you do happen to kill him, come back here and let me know. No good deed should go unrewarded.", sourceObjective = "Find the Stormpike Explosives Expert and kill him. Return to the Frostwolf Explosives Expert when the task is complete.", sourceObjectiveStatus = "unverified-source-field" }
quests[7383] = { id = 7383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: The Burden of the Kaldorei", description = "You must now visit the moonwell that rests under the boughs of the Oracle Tree, far to the northwest. The first and most powerful of our wells, its waters are said to possess the very essence of Elune's Powers.\n\nRetrieve a phial of its water and return to me. I will meet you at the crossroads in front of Darnassus when your task is complete.", sourceObjective = "Fill the Amethyst Phial.", progress = "Along with the druids, the Oracle Tree and the Arch Druid have been carefully monitoring the growth of Teldrassil. But though we have a new home, our immortal lives have not been restored.", completion = "To be in the presence of the Oracle Tree... it is almost to feel wisdom take form. Let me continue the telling...\n\nWith Teldrassil grown, the Arch Druid approached the dragons for their blessings, as the dragons had placed upon Nordrassil in ancient times. But Nozdormu, Lord of Time, refused to give his blessing, chiding the druid for his arrogance. In agreement with Nozdormu, Alexstrasza also refused Staghelm, and without her blessing, Teldrassil's growth has been flawed and unpredictable...", sourceObjectiveStatus = "unverified-source-field" }
quests[7385] = { id = 7385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gallon of Blood", progress = "You have the option of offering larger quantities of the blood taken from our enemies. I will be glad to accept gallon sized offerings, {name}.", completion = "The blood of our enemies has been shed. I shall mix this blood with the rest that has been gathered. Once the offering is complete, the Ice Lord shall show these Stormpike dogs the full wrath of the Frostwolf Clan!" }
quests[7386] = { id = 7386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Cluster", progress = "There are times which you may be entrenched in battle for days or weeks on end. During those longer periods of activity you may end up collecting large clusters of the Frostwolf's storm crystals.\n\nThe Circle accepts such offerings, {name}.", completion = "Well done, {name}. I will use the power of these charms to augment the magic that has already been gathered. When enough power has been amassed, I shall focus the collected energies and call upon the Forest Lord to aid our cause." }
quests[7429] = { id = 7429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Knot!", progress = "It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it.  I think any of the ogres might have it, but I'm not sure if any specific ones do.  Maybe the guards have a better chance of having one...\n\nWhat am I talking about - you have it already, don't you?!  Is that it there??!", completion = "Oh, thank you for freeing me!  You - ranked number one.  Everyone else - ranked number two or lower.\n\nI knew my life was destined for more than just being an appetizer to some ogre!" }
quests[7441] = { id = 7441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pusillin and the Elder Azj'Tordin", description = "I had let my guard down for only one moment, stranger. In my haste to escape the grip of the fallen Prince, I was robbed. A most foul demon, the imp Pusillin, pilfered my book of incantations and the key to the once great halls of Eldre'Thalas.\n\nI no longer hold interest in the key, as I have exchanged my immortality for freedom, but I desperately need my book of incantations.\n\nFind the imp, Pusillin, and recover my book.\n\nSearch the Warpwood Quarter of Dire Maul for Pusillin.", sourceObjective = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.\n\nReturn to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.", progress = "I regret nothing, stranger. The Queen has long since passed. The works of the Shen'Dralar have been marred by the madness of Prince Tortheldrin. I seek only freedom... Escape...", completion = "You have found it! A curse upon that miserable imp. Alas, my material possessions are meager at best. You may choose from what I have to offer.", sourceObjectiveStatus = "unverified-source-field" }
quests[7461] = { id = 7461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Madness Within", description = "Have you heard enough? Are you a <man/woman> of action?\n\nThis madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the pylons to lower the force field. When this is done, destroy Immol'thar. With the Prince's power greatly reduced, attack and end him. Lay the spirits of this city to rest, adventurer.", sourceObjective = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\n\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\n\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest.", progress = "Be wary, adventurer. The Prince is... persuasive.", completion = "We thank you, hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[7462] = { id = 7462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Treasure of the Shen'dralar", description = "In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.You will be able to choose one of these rewards:", sourceObjective = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!", sourceObjectiveStatus = "unverified-source-field" }
quests[7463] = { id = 7463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Refreshment", description = "A {race} mage! How wonderous. I have not seen one of your kind for... oh what is it going on now? 500 years!\n\nI have something that will quench your thirst, but first you must do a task for me.\n\n<Lydros snickers.>\n\nThere is an anomaly in Eldre'Thalas. A water elemental has taken residence in the east wing. His presence must be catalogued!\n\nVenture to the Warpwood Quarter and extract a portion of the elemental essence of the Hydrospawn. Return it to me and I shall teach you a useful cantrip.", sourceObjective = "Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.", progress = "Yes? Do I know you?", completion = "Wonderful! Who are you again? Oh it matters not. What was I supposed to give you? Hrm... well you are a {class}, perhaps you will find this useful.", sourceObjectiveStatus = "unverified-source-field" }
quests[7481] = { id = 7481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elven Legends", description = "Several years ago, a lone elven master named Telmius Dreamseeker fled the devastation of his homeland with several ancient elven artifacts in tow.\n\nOur search for this lost master lead us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.\n\nWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).\n\nYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!", sourceObjective = "Search Dire Maul for Telmius Dreamseeker. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find.", progress = "My associate, the night elf scholar, Runethorn, is recruiting her allies for this task.", completion = "A shame... a tragedy. The items are lost you say? No trace of him, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[7482] = { id = 7482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elven Legends", description = "Several years ago, a lone elven master named Telmius Dreamseeker fled the devastation of his homeland with several ancient elven artifacts in tow.\n\nOur search for this lost master lead us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.\n\nWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).\n\nYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!", sourceObjective = "Search Dire Maul for Telmius Dreamseeker. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find.", progress = "My associate, the tauren sage, Korolusk, is recruiting his allies for this task.", completion = "A shame... a tragedy. The items are lost you say? No trace of him, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[7483] = { id = 7483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Libram of Rapidity", description = "Master Dreamseeker lost the Libram of Rapidity in the east wing. The Libram will allow for a minor haste cantrip to be placed upon your equipment. Parlor tricks, really...\n\nRegardless, if you are interested, you will need to present the Libram along with some basic reagents.\n\nHrm... I believe it also requires blood of heroes, a pristine black diamond, and large brilliant shards. I could be wrong!\n\n<Lydros shrugs.>", sourceObjective = "Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.", progress = "What is it? I have much cataloguing to do!", completion = "<Lydros yawns.>\n\nAs promised, the Arcanum of Rapidity. Don't spend it all in once place.\n\n<Lydros snickers.>", sourceObjectiveStatus = "unverified-source-field" }
quests[7484] = { id = 7484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Libram of Focus", description = "This libram almost aroused interest in one of the younger Lorekeeper's familiars. Poor thing, it was only a few weeks old.\n\nThose among you who are more magically inclined might find this item interesting.\n\nThe Libram of Focus was lost in this wing. I can only assume one of the Highborne spirits holds it in their possession.\n\nBring the Libram along with some large brilliant shards, skin of shadow, and a pristine black diamond and I shall conjure the Arcanum.", sourceObjective = "Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.", progress = "You again? What could you possibly want now?", completion = "Don't hurt yourself when applying the enchantment, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[7485] = { id = 7485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Libram of Protection", description = "He wept like an infant at the loss of this libram. Mind you, I myself have wept over texts - there is no greater loss than that of knowledge and history - but to cry over this nearly useless jumbling of incantations? Preposterous! It left me to believe that the Prince was doing him a favor in flaying the flesh from his bones.\n\nBring the Libram along with a pristine black diamond, large brilliant shards, and a frayed abomination stitching and I shall recreate the Arcanum.\n\nOh, and check the north wing.", sourceObjective = "Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection.", progress = "My patience prevents your suffering.", completion = "Yes, yes... Calm yourself. As promised, here is your Arcanum.", sourceObjectiveStatus = "unverified-source-field" }
quests[7486] = { id = 7486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Reward", description = "{name}, your services to the Warlords surpassed all we could expect from the denizens of this world.\n\nWe do not understand your people's notions of gratitude, or rewarding good works, but in this case... perhaps a reward is warranted.\n\nUnder the surf at the southern base of this island, you will find a coffer.  In it you will find your... reward.\n\nGo, {name}.  Claim your reward.", sourceObjective = "Claim your reward from Hydraxis' Coffer.", completion = "Hydraxis' voice descends from the waters' surface...\n\n\"Choose that which best suits you, {name}.  May it protect you against the foes of the Waterlords.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[7487] = { id = 7487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attunement to the Core", description = "Rifts stir, tear, and collapse all around us, {race}. Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord.\n\nSurprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel.\n\nI assure you, the portal is there and access is possible.\n\nI've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment. Return it to me and I shall attune your essence with the portal.", sourceObjective = "Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.", sourceObjectiveStatus = "unverified-source-field" }
quests[7488] = { id = 7488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lethtendris's Web", description = "The mage Lethtendris, a vicious blood elf whose brutality is matched only by her twisted addiction to magic, has fled into Dire Maul.  She has created a device, a web to ensnare the magical energies of that place and we fear that, if left unchecked, she will cause irreparable damage to our world!\n\nStop her, {name}.  Find her and retrieve her web.  She is likely near the satyrs in Warpwood Quarter of Dire Maul.  Bring the web to me so that its power may be released safely back into the wilds...", sourceObjective = "Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas.", progress = "Do you have the web, {name}?  Its concentrated magical energy must be dissipated!", completion = "You retrieved the web!  Well done, {name}!  Lethtendris, like many elves of her ilk, are blind to the dangers the abuse of magic can cause to our world.  They believe they are masters of magic; they do not realize that they are slaves to their own addiction.  Her death saddens me, but it was necessary.\n\nThank you, {name}.  I will have the energies within the web released safely over a wide area, and then I'll destroy it to prevent future magical exploits.", sourceObjectiveStatus = "unverified-source-field" }
quests[7489] = { id = 7489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lethtendris's Web", description = "The blood elf Lethtendris has overstepped her bounds.  So eager was she to gather magical power that she defied her brethren and created a device of insidious design, a web meant to siphon the tainted magical energies of Dire Maul.  Even now she gathers those energies and plans to release them against her enemies.\n\nLethtendris must be stopped.  Find her within the Warpwood Quarter of Dire Maul, defeat her and bring her web to me so that it might be returned to more clear-headed blood elves for study.", sourceObjective = "Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.", progress = "{name}, do you have Lethtendris's Web?", completion = "You have done well, {name}.  This web holds within it vast stores of the magic of Dire Maul, and I fear what damage may be unleashed if those energies were harnessed by one so irresponsible as Lethtendris.  I am saddened by her death, but I know that she could never part with her web while alive.\n\nThank you, {name}.  I will send the web to students of magic more responsible than Lethtendris.  They will be the new wardens of its power.", sourceObjectiveStatus = "unverified-source-field" }
quests[7490] = { id = 7490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory for the Horde", description = "You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to your Warchief.", sourceObjective = "Take the Head of Onyxia to Garrosh in Orgrimmar.", progress = "<Thrall's stoic demeanor changes for a split second when he sees the enormous head of Onyxia. The mighty Doomhammer was nearly unsheathed.>", completion = "This is a great victory for the Horde, {name}. So many times you have honored your Warchief. It is time for the Warchief to honor you.", sourceObjectiveStatus = "unverified-source-field" }
quests[7491] = { id = 7491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For All To See", description = "Overlord Runthak awaits your arrival in the Valley of Strength.\n\n<The Warchief salutes you.>\n\nDo not keep your public waiting, hero.", sourceObjective = "Seek out Overlord Runthak in the Valley of Strength.", completion = "Choose your reward and let the celebration of your glorious victory begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[7492] = { id = 7492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camp Mojache", description = "Talo Thornhoof, a Tauren elder in Feralas, sends a request for aid.  He offered few details, but he did say that he needs agents for a matter both delicate... and dire.\n\nServe the Horde, {name}.  Go to Camp Mojache in Feralas and speak with Talo.", sourceObjective = "Speak with Talo Thornhoof at Camp Mojache in Feralas.", completion = "Ah, it is good to see a {class} heed my summons.  I have need of your services, {name}, and fear they will take you down a dangerous path...\n\nA path into Dire Maul.", sourceObjectiveStatus = "unverified-source-field" }
quests[7493] = { id = 7493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Journey Has Just Begun", sourceObjective = "A dragon slayer and a seasoned leatherworker? You do not cease to astonish, hero. I am humbled.\n\nPlease accept what I am about to teach you. This knowledge will prove to be invaluable if you are to destroy what remains of the Black Dragonflight.\n\nCreate the cloak from the scales of the brood mother. It will protect you and your allies against the incendiary breath of the Lord of Blackrock... Nefarian.", sourceObjectiveStatus = "unverified-source-field" }
quests[7494] = { id = 7494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathermoon Stronghold", description = "{name}!  Your aid is needed in Feralas!\n\nAn outlaw mage, Lethtendris, has fled to the ancient elven ruins Eldre'thalas, now called Dire Maul.  It is believed she has an item of dangerous magical energy which must be recovered.\n\nLatronicus Moonspear requests agents to enter Dire Maul and retrieve the item from Lethtendris.\n\nServe the Alliance!  Seek out Latronicus at the Feathermoon Stronghold in Feralas.", sourceObjective = "Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas.", completion = "Hail, {name}.  I am pleased to see you, but regret that our meeting is not under more pleasant conditions.\n\nListen close, for I have a vital task for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[7495] = { id = 7495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory for the Alliance", description = "You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to the King Varian Wrynn.", sourceObjective = "Take the Head of Onyxia to King Varian Wrynn in Stormwind.", progress = "By Uther's beard!", completion = "For so many years I was held under her captivating gaze. Finally, to see justice meted and the honor of Stormwind restored! Today, we celebrate this glorious victory!", sourceObjectiveStatus = "unverified-source-field" }
quests[7496] = { id = 7496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Celebrating Good Times", description = "Seek out Major Mattingly in the Valley of Heroes, {name}. He will be expecting you...", sourceObjective = "Seek out Major Mattingly in the Valley of Heroes.", completion = "Few are graced with such ceremony, {name}. Please, choose your reward so that we may begin the celebration.", sourceObjectiveStatus = "unverified-source-field" }
quests[7497] = { id = 7497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Journey Has Just Begun", sourceObjective = "A dragon slayer and a seasoned leatherworker? You do not cease to astonish, hero. I am humbled.\n\nPlease accept what I am about to teach you. This knowledge will prove to be invaluable if you are to destroy what remains of the Black Dragonflight.\n\nCreate the cloak from the scales of the brood mother. It will protect you and your allies against the incendiary breath of the Lord of Blackrock... Nefarian.", sourceObjectiveStatus = "unverified-source-field" }
quests[7498] = { id = 7498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garona: A Study on Stealth and Treachery", description = "The tome carries the mark of the Athenaeum.", sourceObjective = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Excellent work, {race}. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", sourceObjectiveStatus = "unverified-source-field" }
