quests[7505] = { id = 7505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Shock and You", description = "The tome carries the mark of the Athenaeum.", sourceObjective = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Excellent work, {race}. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", sourceObjectiveStatus = "unverified-source-field" }
quests[7506] = { id = 7506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Dream...", description = "The tome carries the mark of the Athenaeum.", sourceObjective = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Excellent work, {race}. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", sourceObjectiveStatus = "unverified-source-field" }
quests[7507] = { id = 7507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nostro's Compendium", description = "You have uncovered something of great importance. This book is unlike any that you have seen.\n\nIt would appear as if someone or something has managed to shatter the seal of Athenaeum. The text within is garbled and barely legible.", sourceObjective = "Return Nostro's Compendium of Dragon Slaying to the Athenaeum.", progress = "Ah, one of our greatest compilations. This one has been missing for ages.", completion = "You could have gotten quite a lot of gold for this book on the black market, {name}. Especially since the protective seal has been broken, leaving the secrets of dragon slaying viewable to any with the requisite intellect to consume the knowledge held within the sacred pages.\n\nPerhaps a grand reward is in order... Well, a reward that will require enormous effort to obtain.", sourceObjectiveStatus = "unverified-source-field" }
quests[7508] = { id = 7508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forging of Quel'Serrar", description = "If you wish to take on this task, present Lydros with the dull blade.", sourceObjective = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros.", progress = "Excellent, let us begin...", completion = "If you manage to enter the lair of the dragon, heat the blade under her fiery breath, and ultimately temper it in her blood, I shall bind the blade for your use.", sourceObjectiveStatus = "unverified-source-field" }
quests[7509] = { id = 7509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forging of Quel'Serrar", description = "Take the unfired ancient blade to the lair of Onyxia and engage her in battle.\n\nSome trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon.\n\nPlunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade.", sourceObjective = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.\n\nThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.\n\nDo this and Quel'Serrar will be yours.", progress = "Perhaps one day, another will wield the prismatic blade.", completion = "<Lydros murmurs something unintelligible.>\n\nAs promised, {class}, the blade of Quel'Serrar.", sourceObjectiveStatus = "unverified-source-field" }
quests[7541] = { id = 7541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Service to the Horde", sourceObjective = "It will take time for our scholars to study the pendant you brought us.  But for your service to the Horde I would like to offer you a small token.\n\nThank you, {name}.  Your acts bring honor to you, and to us.", sourceObjectiveStatus = "unverified-source-field" }
quests[7562] = { id = 7562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'zul Bloodbringer", description = "{name}, your delvings into the dark arts are deep.  Your mastery over otherworldly denizens has grown so strong... perhaps you are ready to bind to you one of the infamous dreadsteeds.\n\nThe ritual to summon the beast from its home requires great power and resources, but if you desire to dominate that epic mount, then speak with Mor'zul Bloodbringer.  He is camped near the Altar of Storms in the Burning Steppes.\n\nGo, {name}.  This quest will be perilous, but a Warlock of your stature does not shy from danger!", sourceObjective = "Speak with Mor'zul Bloodbringer at the Altar of Storms in the Burning Steppes.", completion = "Greetings, {name}, and welcome.  Are you here to study near the Altar of Storms as I am, perhaps to harness its energy for some hidden purpose...\n\nOr... are you here to speak with me?  Yes, I believe you are.\n\nYou want to master a dreadsteed?  Such is no easy task.  It will cost you no small amounts of blood, sweat... and of course gold.  But a dreadsteed of Xoroth is a prize well worth winning so if interested, listen on...", sourceObjectiveStatus = "unverified-source-field" }
quests[7563] = { id = 7563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rage of Blood", description = "The dreadsteeds dwell on another world, on the fiery Plains of Xoroth, and to bind one of those famed beasts you must invoke powerful glyphs.  I can scribe the glyphs on a parchment for you, but first I will need a special ink.\n\nIn distant Winterspring there dwells a race of owl beasts.  Once pure creatures, they were turned mad by the demonic emanations of the Darkwhisper Gorge and now roam the snows in a frenzy.\n\nTheir blood is what I need to ink your parchment.  Bring it to me.", sourceObjective = "Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes.", progress = "Have you seen the raging owl beasts, {name}?  The magic of those creatures is strong, and it concentrates in the blood that flows through their torturted forms.", completion = "Ah, very good.  I will have this blood distilled into an ink and use it for the parchment I promised you.  And perhaps I will save just a little for myself, as I hear its taste is quite euphoric...", sourceObjectiveStatus = "unverified-source-field" }
quests[7564] = { id = 7564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildeyes", description = "My servant, Gorzeeki, is an alchemist of some skill.  He can prepare the ink I will need for your parchment.  I gathered together the blood you acquired; take it to Gorzeeki so that he can begin his work.", sourceObjective = "Bring the Case of Blood to Gorzeeki Wildeyes at the Altar of Storms in the Burning Steppes.", progress = "You have something for me?  It's not a big, juicy spider, is it?  Or maybe a roach?  I hope it's still alive... I so love chewing on them when they're still alive...", completion = "Oh, it's blood.  It must be from master Mor'zul then.  He is so enamored with the stuff, and loves to see it spilled.  I, however, prefer it coursing through the veins of a small rodent.  It stays warm that way... until you want it.\n\nThis is powerful blood.  Mor'zul must be making another parchment to summon a dreadsteed!  How exciting!\n\nIf that's true, and you're going to perform the ritual, then... you're going to need a lot more than blood, my friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[7581] = { id = 7581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prison's Bindings", description = "You must retrieve bindings for the prison of the Doomguard from lesser demons.\n\nThe blood of the Wildspawn satyr that occupy Dire Maul should do nicely. The coagulated blood will bond the Hederine shards and power the crystal prison.", sourceObjective = "Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done.", progress = "Only the blood of Wildspawn satyr will suffice.", completion = "Ah, a most excellent recovery. The blood will suppress the Doomguard's magical defenses.", sourceObjectiveStatus = "unverified-source-field" }
quests[7582] = { id = 7582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prison's Casing", description = "The Hederine demons that occupy the foothills of Mount Hyjal secrete powerful fel poisons, which if left to mature, harden into a dense anti-magic crystal. These crystals have come to be known as Tears of the Hederine.\n\nNot even the immense power of a Doomguard could break the walls of a prison constructed from this material.\n\nTravel to Darkwhisper Gorge in Winterspring and recover the Tears.", sourceObjective = "Travel to Darkwhisper Gorge in Winterspring and recover 5 Tears of the Hederine from the Hederine demons that occupy the gorge. Return to Daio in the Tainted Scar when you have completed this task.", progress = "The Hederine will not give up their precious gems without a fight, {name}.", completion = "I merely need to combine the blood of the Wildspawn with these crystals and the prison shall be ready for use.", sourceObjectiveStatus = "unverified-source-field" }
quests[7583] = { id = 7583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suppression", description = "The prison is ready. Now for the most difficult portion of this task.\n\nYou must find and capture a Doomguard Commander within the Tainted Scar using this crystal prison.\n\nBe warned! A Doomguard is a cunning and lethal adversary and will seek to destroy you as you begin the ritual of imprisonment. It will flail wildly in its attempts to escape imprisonment.\n\nIt will focus on nothing but you, {name}. Because of this, I must recommend that you take companions capable of keeping you alive!", sourceObjective = "Venture forth into the Tainted Scar and locate a Doomguard Commander.\n\nUse the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.\n\nShould you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar.", progress = "Hrm? Well?", completion = "You have done as I have asked. You are ready to be given the knowledge to conjure and control the beast.", sourceObjectiveStatus = "unverified-source-field" }
quests[7601] = { id = 7601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Niby Commands", description = "If I am to teach you the secrets of summoning an infernal servant, you must destroy Kroshius and bring me the infernal core from his burning remains. This, however, is not as easy as it sounds. Kroshius has all but burned out completely. You must reignite his corpse and raise him from the rubble. To do this, however, you must gather some components from other demonic entities.\n\nMy imp, Impsy, shall set you on your way.", sourceObjective = "Speak with Impsy in Felwood.", completion = "Oh boy, here we go again.", sourceObjectiveStatus = "unverified-source-field" }
quests[7602] = { id = 7602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flawless Fel Essence", description = "If you're going to reanimate Kroshius, you're going to need Fel fire. I can make Fel fire but it's going to require some components.\n\nYou need to bring me flawless Fel essences from three distinct regions of the world.\n\nThe Legashi Satyrs of Azshara will have the first essence type; the Jaedenar legionnaires of Jaedenar the second type and the felguard sentries of the Blasted Lands the third.\n\nBring me back one of each essence type and I will create the Fel fire, allowing you to reanimate Kroshius.", sourceObjective = "Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.\n\nThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.\n\nRecover the Flawless Fel Essences and return  to Impsy in Felwood.", progress = "Don't tell anyone this but Niby is daft.", completion = "Give me a minute and I'll combine the essences into Fel fire.", sourceObjectiveStatus = "unverified-source-field" }
quests[7603] = { id = 7603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kroshius' Infernal Core", description = "Kroshius lays in a heap to the northeast, in the Shatter Scar Vale. Take this Fel fire and use it on his remains. The fire should reanimate the fallen infernal.\n\nAt this point, I fully expect him to kill you and your minion.\n\nIf by some miracle you happen to kill Kroshius, take his infernal core and return it to Niby.", sourceObjective = "Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.\n\nReturn Kroshius' Infernal Core to Niby the Almighty in Felwood.", progress = "Did you get lost?", completion = "A deal is a deal! Quickly, take this and write this down. I don't have time! My greatest conjuration is upon us!", sourceObjectiveStatus = "unverified-source-field" }
quests[7604] = { id = 7604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Binding Contract", description = "The undersigned hereby declares that the Sulfuron ingot they are delivering to the Thorium Brotherhood (TB Ltd.) is genuine and not a facsimile thereof. The undersigned also acknowledges that any harm that should come to <him/her> as a result of attempting to build, forge, find, create, sell, or eat Sulfuras, is not the responsibility or fault of TB Ltd.\n\nBy signing this contract, you are agreeing to all terms listed herein.\n\n_________________\n\nSignature", sourceObjective = "Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.", progress = "Do we have a deal?", completion = "It has been a pleasure doing business with you, {name}!\n\nOn behalf of TB Ltd., I wish you luck in your search for Sulfuras!", sourceObjectiveStatus = "unverified-source-field" }
quests[7621] = { id = 7621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Warning", sourceObjective = "{class}, you are about to undergo a rigorous series of events which shall test all of your abilities.\n\nI suggest that you listen to the story that I have to tell.\n\nBe warned, you must complete this task alone. It is recommended that your allies remain at a distance. Interference by outside agents will result in a most severe punishment.\n\nDestiny has led you and you alone here. Battle with honor. Harness the Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[7622] = { id = 7622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Balance of Light and Shadow", description = "You must do what I could not: Save the peasants that were cut down while fleeing from Stratholme.\n\nThey will walk towards the light, you must ensure their survival. Should too many fall, our cursed existence shall continue - you will have failed.\n\nEvery ability, prayer, and spell that you have learned will be tested. May the Light protect you, {name}.", sourceObjective = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\n\nYou may view the Death Post to view how many Peasants have been slain.", completion = "Your tenacity and courage are astounding, {class}. You have earned the right to hold the Splinter of Nordrassil. Only one task remains: The Eye of Shadow must be recovered. Scour the world.", sourceObjectiveStatus = "unverified-source-field" }
quests[7623] = { id = 7623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Banehollow", description = "Mor'zul says that you want to open a portal to Xoroth.  To do that, you'll need Xorothian stardust.  That's not easy to find on Azeroth!\n\nThere is one being who might have some: Lord Banehollow in Jaedenar, the seat of the Shadow Council!  Speak with him and he might part with the stardust.\n\nBut if you're going to Jaedenar, then you'll need to cloak yourself in the Shadow Council's own flavor of evil.  That will require some of my shadowy potions, and that will cost you...", sourceObjective = "Purchase Shadowy Potions from Gorzeeki Wildeyes at the Altar of Storms in the Burning Steppes.\n\nUse the potions to travel through Jaedenar in Felwood, and speak with Lord Banehollow inside the Shadow Hold.", completion = "My patience spans the millenia, {class}.  But do not think that allows you more than an instant of my time...", sourceObjectiveStatus = "unverified-source-field" }
quests[7624] = { id = 7624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulathek the Traitor", description = "You wish to enter my good graces?  Then kill for me.\n\nMy servant, Ulathek, is pathetic how he grovels before me, all the while plotting with Lord Hel'nurath on Xoroth.  Hel'nurath plans to usurp my power here, and Ulathek is his spy...\n\nProve that you serve me and not my rivals.  Confront Ulathek in his quarters, in the Shadow Hold to the west.  Tell him that I know his secret and watch as fear grips him.  Then, bring me the traitor's heart!", sourceObjective = "Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar.", progress = "I can already taste the heart of Ulathek on my lips.  So sweet is the flesh of a traitor...", completion = "Ah, how splendid!  After rotting a week, this heart will prove a succulent treat!  Perhaps I will send for Ulathek's head and place it before me as I eat...\n\nYou have done me a service, {class}, and so my patience for you has grown.  Marginally.", sourceObjectiveStatus = "unverified-source-field" }
quests[7625] = { id = 7625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xorothian Stardust", description = "So you come to me seeking Xorothian stardust?  You wish to open a portal to Xoroth, the domain of Hel'nurath my rival?  Perhaps you plan to steal from him one of his precious dreadsteeds?\n\nVery well.  My servant Ur'dan has a supply of Xorothian stardust.  You may obtain it from him... if you can pay the price.", sourceObjective = "Purchase Xorothian Stardust from Ur'dan inside the Shadow Hold at Jaedenar in Felwood. Bring it to Gorzeeki Wildeyes in the Burning Steppes.", progress = "Have you been to Jaedenar, {name}?  Did you get the stardust from Lord Banehollow?", completion = "There it is!  I can hardly believe you got it!  You must have struck a big deal with that Dreadlord or else paid a large sum, or both!\n\nMor'zul will have his ink very soon and then he can finally make the glyph parchment, so you can open a portal to Xoroth and pull through it one of the famed dreadsteeds!", sourceObjectiveStatus = "unverified-source-field" }
quests[7626] = { id = 7626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bell of Dethmoora", description = "A Bell of Dethmoora, named after the late warlock Dethmoora Darkeyes, is one of the three tools needed to create a Circle of Greater Summoning.  When properly atuned with the Wheel and the Candle, these items conduct vast stores of arcane power.\n\nMy servant Gorzeeki can construct such a bell, but to do so he will need a large supply of elixirs of shadow power.  Procure the elixirs from an alchemist and bring them to Gorzeeki.", sourceObjective = "Bring 2 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes.", progress = "You have those elixirs, {name}?  Mor'zul told me you need a Bell of Dethmoora, and making one of those takes a lot of shadow power!", completion = "Very good!  I hope these elixirs weren't too hard to get.  Sometimes alchemists can be so miserly with their creations...\n\nI'll make the bell and keep it until you're ready for your ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[7627] = { id = 7627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wheel of the Black March", description = "A Wheel of the Black March contains and directs the violent energies required for the Circle of Greater Summoning.  For Gozeeki to construct a wheel, he will need both large brilliant shards from an enchanter, and dark iron ore from a master miner.\n\nAcquire these and bring them to my servant.", sourceObjective = "Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes.", progress = "The Wheel of the Black March isn't easy to make, and takes a lot of materials.  Have you gathered them yet?", completion = "There they are!  I hear that dark iron ore is only found in the depths of Blackrock, and I'm sure these shards weren't easy to find either.  I am often awed at the dedication you warlocks have.  If you instead bent all that energy into the art of bug catching, oh... such a feast you would enjoy!\n\nSorry, a small digression.  I'll create the wheel and keep it for you until you're ready for your ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[7628] = { id = 7628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doomsday Candle", description = "A Doomsday Candle stores fire and directs it at those who would disrupt your ritual.  When creating your Circle of Greater Summoning, if your candle is lit then any wayward demons will be burned by its flames!\n\nContaining that fire is not easy, and requires the essence within the scales of a black dragon.  Acquire those scales from a skinner and bring them to Gorzeeki Wildeyes.", sourceObjective = "Bring 3 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes.", progress = "Did you bring the dragonscales, {name}?  I don't want to start on the candle until I have them... or I might blow up the whole camp!", completion = "Ah, very good.  I'll need these to contain the fires of the candle.  Now that I have the scales, I'll make the candle and hold onto it until you're ready to begin your ritual for the Circle of Greater Summoning.", sourceObjectiveStatus = "unverified-source-field" }
quests[7629] = { id = 7629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imp Delivery", description = "There is one more process required for Mor'zul's parchment; I need paper infused with Xorothian stardust.  And... I'm afraid I can't do that here.  I don't have the equipment!\n\nThere is an alchemy lab, however, with everything needed.  It's in the Scholomance, on the isle of Caer Darrow in the Plaguelands.\n\nI can't make the trip, but here - take this jar.  There's an imp inside who is quite clever.  Let him out at the alchemy lab and he'll infuse the parchment.", sourceObjective = "Bring the Imp in a Jar to the alchemy lab in the Scholomance. After the parchment is created, return the jar to Gorzeeki Wildeyes.", progress = "Have you been to the Scholomance, {name}?  Has the imp yet infused the parchment with the stardust?", completion = "Ah, good.  J'eevee created the parchment.  How was the Scholomance?  Charming, don't you think?  And the bugs there... I hear they're delicious!\n\nWell done, {name}, and thank you for returning my jar.  I've had it for a long time... and it's not for sale!", sourceObjectiveStatus = "unverified-source-field" }
quests[7630] = { id = 7630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcanite", description = "Now that the Bell, Wheel and Candle are made, I should make a black lodestone.  During your ritual, you'll need that lodestone to maintain the other ritual objects if they should fail.\n\nTo make the lodestone, I require arcanite.  Do you have any?  If not, then... you'll have to get the arcanite from an alchemist.\n\nReturn to me when you have the arcanite, and then I'll make the black lodestone.", sourceObjective = "Bring 1 Arcanite Bar to Gorzeeki in the Burning Steppes.", progress = "Do you have the arcanite, {name}?  Once I have it I can make you the black lodestone.", completion = "You got it!  Nicely done!  Now I can create the lodestone.  When you're finally ready for your ritual to create the Circle of Greater Summoning, you'll want  a lodestone to make sure the ritual doesn't fizzle out!", sourceObjectiveStatus = "unverified-source-field" }
quests[7631] = { id = 7631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadsteed of Xoroth", description = "All the preparations are made.  Now, you must perform the ritual to create a Circle of Greater Summoning, then use the parchment infused with Xorothian stardust... to open a portal to Xoroth.\n\nI have written the instructions for the ritual onto a scroll.  Study it closely, for you must perform each step exactly if you wish to succeed.\n\nFortune to you, {name}.  And may the souls of your enemies swiftly find their way into your shard pouch.", sourceObjective = "Read Mor'zul's Instructions. Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you.\n\nProvided item:", completion = "The Xorothian Dreadsteed's spirit is beaten.  Although rage pulses through its ghostly flanks, you know that the beast's soul is yours...\n\nIt whispers dark magic into your mind and instills within you the knowledge to summon a Dreadsteed.", sourceObjectiveStatus = "unverified-source-field" }
quests[7632] = { id = 7632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancient Leaf", description = "The epidermis of the leaf glows a bright green. The surface is extremely rugose, exposing several veins and wrinkles.\n\nIf you had to take a guess, you would say this leaf came from something ancient and powerful.\n\nMaybe you should find the original owner of this leaf?", sourceObjective = "Find the owner of the Ancient Petrified Leaf. Good luck, {name}; It's a big world.", progress = "<Vartrus groans.>", completion = "Of course I recognize my own leaves. Look at that! It's in perfect condition.\n\nHow good of you to return it, {class}.\n\nPerhaps you could be of service to us and we to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[7633] = { id = 7633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Introduction", sourceObjective = "Your diligence and integrity has been noted, {class}.\n\nWe are Ancients: Protectors of this once great forest. Our physical forms were destroyed 10,000 years ago when Archimonde and the Burning Legion marched upon Hyjal. Our spirits, however, remain intact.\n\nThere are tasks that we can offer. Tasks that if completed will open up the secrets of the Ancients to you.\n\nKnow this, should you complete these tasks, merely return to this rock and we shall answer the calling.", sourceObjectiveStatus = "unverified-source-field" }
quests[7634] = { id = 7634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Sinew Wrapped Lamina", description = "Greetings, {class}. I am Hastat, Ancient of Lore. I hold knowledge lost eons ago.\n\nWith the proper binding, one of my leaves can serve as a quiver the likes of which has not been seen in 10,000 years. A quiver that when accompanied by a bow of Ancients, could grant untold powers.\n\nReturn here with sinew from an adult blue dragon and this quiver shall be yours.", sourceObjective = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood.", progress = "Welcome back, young {class}.", completion = "May my leaves provide your arrows protection from harm. May your arrows strike true. May the enemies of our world be smitten.", sourceObjectiveStatus = "unverified-source-field" }
